window.ETSDATA=window.ETSDATA||{};window.ETSDATA[21]={"lc":null,"rc":{"p5":[{"n":101,"q":"Residents made an ------- to the city council to try to get the speed limit lowered in their neighborhood.","opts":["appealingly","appealed","appeal","appeals"],"ans":"C","xp":"Từ loại. Sau mạo từ 'an' và trước giới từ 'to' cần một danh từ số ít → (C) appeal 'lời kêu gọi, lời thỉnh cầu'. Cụm make an appeal to = kêu gọi, thỉnh cầu ai. (A) trạng từ, (B) động từ quá khứ, (D) danh từ số nhiều/động từ chia ngôi 3 – không đi với 'an'.\nDịch: Cư dân đã gửi lời thỉnh cầu lên hội đồng thành phố để cố gắng giảm giới hạn tốc độ trong khu phố của họ."},{"n":102,"q":"All chemicals at the lab must be ------- in air-tight containers with clear labels on the front.","opts":["served","estimated","stored","resolved"],"ans":"C","xp":"Từ vựng (động từ). 'be ------- in air-tight containers' = được ... trong hộp kín → (C) stored 'được cất giữ, bảo quản'. (A) served 'phục vụ', (B) estimated 'ước tính', (D) resolved 'giải quyết' không hợp nghĩa.\nDịch: Tất cả hóa chất trong phòng thí nghiệm phải được bảo quản trong hộp kín khí có dán nhãn rõ ràng ở mặt trước."},{"n":103,"q":"To open a new account at Columbus Library, a photo ID ------- proof of address are required.","opts":["and","yet","so","through"],"ans":"A","xp":"Liên từ đẳng lập. Nối hai danh từ 'a photo ID' và 'proof of address', động từ số nhiều 'are' → cần (A) and 'và'. (B) yet 'nhưng', (C) so 'vì vậy' nối mệnh đề; (D) through 'xuyên qua' là giới từ.\nDịch: Để mở tài khoản mới tại Thư viện Columbus, cần có giấy tờ tùy thân có ảnh và giấy tờ chứng minh địa chỉ."},{"n":104,"q":"Please double-check the inventory list carefully because ------- must be turned in to the manager today.","opts":["their","it","her","you"],"ans":"B","xp":"Đại từ. Chỗ trống làm chủ ngữ của 'must be turned in', thay cho 'the inventory list' (số ít, vật) → (B) it. (A) their là tính từ sở hữu, (C) her chỉ người, (D) you không hợp nghĩa.\nDịch: Vui lòng kiểm tra kỹ lại danh sách hàng tồn kho vì nó phải được nộp cho quản lý trong hôm nay."},{"n":105,"q":"Employees need ------- three years' experience at their home branch before applying to transfer overseas.","opts":[" three years' experience at their home branch before applying to transfer overseas.","even if","just as","so that"],"ans":"D","xp":"Cụm từ cố định. Trước số lượng 'three years' experience' → (D) at least 'ít nhất'. (A) even if 'ngay cả khi', (C) so that 'để mà' là liên từ, cần mệnh đề theo sau; (B) just as 'đúng lúc/giống như' không hợp.\nDịch: Nhân viên cần ít nhất ba năm kinh nghiệm tại chi nhánh gốc trước khi xin chuyển công tác ra nước ngoài."},{"n":106,"q":"------- the chef arranges the food on the plate, one of the servers should bring it out to the person who ordered it.","opts":["For instance","Still","As soon as","Meanwhile"],"ans":"C","xp":"Liên từ phụ thuộc. Câu có hai mệnh đề (the chef arranges... / one of the servers should bring...) → cần liên từ nối: (C) As soon as 'ngay khi'. (A) For instance 'ví dụ', (B) Still 'tuy vậy', (D) Meanwhile 'trong khi đó' là trạng từ, không nối được 2 mệnh đề.\nDịch: Ngay khi đầu bếp bày món ăn ra đĩa, một nhân viên phục vụ nên mang nó ra cho người đã gọi món."},{"n":107,"q":"The HR team is having difficulty filling the security director ------- with a qualified applicant.","opts":["career","worker","background","position"],"ans":"D","xp":"Từ vựng (danh từ). 'fill the security director -------' = tuyển người cho vị trí giám đốc an ninh → (D) position 'vị trí, chức vụ'. fill a position = tuyển người vào vị trí. (A) career 'sự nghiệp', (B) worker 'công nhân', (C) background 'lý lịch'.\nDịch: Nhóm nhân sự đang gặp khó khăn trong việc tìm ứng viên đủ năng lực cho vị trí giám đốc an ninh."},{"n":108,"q":"The hospital administrator ------- the health services of the entire facility to provide patients with excellent care.","opts":["receives","looks","predicts","oversees"],"ans":"D","xp":"Từ vựng (động từ). Người quản lý bệnh viện ... dịch vụ y tế của cả cơ sở → (D) oversees 'giám sát, quản lý'. (A) receives 'nhận', (B) looks phải đi với giới từ (look at/after), (C) predicts 'dự đoán'.\nDịch: Người quản lý bệnh viện giám sát các dịch vụ y tế của toàn bộ cơ sở để mang lại sự chăm sóc tuyệt vời cho bệnh nhân."},{"n":109,"q":"Reporters took photographs ------- the opening ceremony of the Maxwell Music Festival.","opts":["except","while","besides","during"],"ans":"D","xp":"Giới từ. Sau chỗ trống là cụm danh từ 'the opening ceremony' (một sự kiện) → (D) during 'trong suốt (sự kiện)'. (A) except 'ngoại trừ', (C) besides 'ngoài ra' không hợp nghĩa; (B) while là liên từ, cần mệnh đề.\nDịch: Các phóng viên đã chụp ảnh trong suốt lễ khai mạc Lễ hội Âm nhạc Maxwell."},{"n":110,"q":"The supplies in the storage room are for everyone, so workers can take ------- they need.","opts":["these","many","whatever","that"],"ans":"C","xp":"Đại từ quan hệ phức. 'take ------- they need' – chỗ trống vừa làm tân ngữ của 'take' vừa là tân ngữ của 'need' → (C) whatever 'bất cứ thứ gì'. (A) these, (B) many, (D) that không nối được mệnh đề như vậy.\nDịch: Đồ dùng trong phòng kho là của mọi người, nên nhân viên có thể lấy bất cứ thứ gì họ cần."},{"n":111,"q":"The responsibilities of each team member should be explained as ------- as possible.","opts":["clearest","clarity","clearly","clearer"],"ans":"C","xp":"Từ loại. Cấu trúc 'as + tính từ/trạng từ + as possible'; chỗ trống bổ nghĩa cho động từ 'be explained' → cần trạng từ (C) clearly 'một cách rõ ràng'. (A)(D) là tính từ so sánh (không dùng giữa as...as), (B) danh từ.\nDịch: Trách nhiệm của từng thành viên trong nhóm nên được giải thích càng rõ ràng càng tốt."},{"n":112,"q":"The senatorial race could be won by either major candidate, according to the most ------- poll.","opts":["fragile","recent","entire","consecutive"],"ans":"B","xp":"Từ vựng (tính từ). 'the most ------- poll' = cuộc thăm dò ý kiến ... nhất → (B) recent 'gần đây' (the most recent = mới nhất). (A) fragile 'dễ vỡ', (C) entire 'toàn bộ', (D) consecutive 'liên tiếp'.\nDịch: Theo cuộc thăm dò ý kiến mới nhất, cuộc đua vào thượng viện có thể thuộc về một trong hai ứng viên lớn."},{"n":113,"q":"Because checked bags are often stacked up, it is ------- for travelers to put fragile items in their carry-ons.","opts":["advises","advice","advising","advisable"],"ans":"D","xp":"Từ loại. Cấu trúc 'it is + tính từ + for sb to V' → cần tính từ (D) advisable 'nên, được khuyên'. (A) động từ, (B) danh từ, (C) V-ing.\nDịch: Vì hành lý ký gửi thường bị xếp chồng lên nhau, hành khách nên để đồ dễ vỡ trong hành lý xách tay."},{"n":114,"q":"The laboratory's equipment is ------- cleaned thoroughly after use to avoid cross-contamination between projects.","opts":["much","afterward","straight","always"],"ans":"D","xp":"Trạng từ. Vị trí giữa 'is' và 'cleaned' cần trạng từ chỉ tần suất → (D) always 'luôn luôn'. (A) much không đứng ở đây với nghĩa này, (B) afterward 'sau đó' thường đứng cuối câu, (C) straight 'thẳng'.\nDịch: Thiết bị của phòng thí nghiệm luôn được làm sạch kỹ lưỡng sau khi sử dụng để tránh lây nhiễm chéo giữa các dự án."},{"n":115,"q":"The town's mayor made a generous donation to the fundraiser, ------- the total to over twenty-five thousand dollars.","opts":["brings","bring","bringing","brought"],"ans":"C","xp":"Phân từ (rút gọn mệnh đề). Câu đã có động từ chính 'made', sau dấu phẩy cần cụm phân từ chỉ kết quả, mang nghĩa chủ động (khoản quyên góp đưa tổng số lên...) → (C) bringing. (A)(B) là động từ chia, (D) brought mang nghĩa bị động.\nDịch: Thị trưởng thị trấn đã quyên góp hào phóng cho buổi gây quỹ, đưa tổng số tiền lên hơn hai mươi lăm nghìn đô la."},{"n":116,"q":"The small business owner decided to use a stock photo database ------- hire a full-time photographer.","opts":["for example","with regard to","in case","rather than"],"ans":"D","xp":"Giới từ/cụm liên kết. So sánh hai lựa chọn 'use a stock photo database' và 'hire a full-time photographer' → (D) rather than 'thay vì'. (A) for example 'ví dụ', (B) with regard to 'về việc', (C) in case 'phòng khi' không hợp.\nDịch: Chủ doanh nghiệp nhỏ quyết định dùng kho ảnh có sẵn thay vì thuê một nhiếp ảnh gia toàn thời gian."},{"n":117,"q":"The new cooking classes at the Crestline Institute are aimed ------- at young adults living on their own for the first time.","opts":["specify","specificity","specifically","specific"],"ans":"C","xp":"Từ loại. Chỗ trống bổ nghĩa cho cụm 'aimed at' (be aimed ... at) → cần trạng từ (C) specifically 'đặc biệt, cụ thể'. (A) động từ, (B) danh từ, (D) tính từ.\nDịch: Các lớp nấu ăn mới tại Viện Crestline được thiết kế đặc biệt dành cho người trẻ lần đầu tiên sống tự lập."},{"n":118,"q":"The journal article states that the research team's ------- are confirmation of the medication's effectiveness.","opts":["finding","findings","find","found"],"ans":"B","xp":"Danh từ số ít/số nhiều. Sau sở hữu 'team's' cần danh từ; động từ 'are' số nhiều → (B) findings 'những phát hiện, kết quả nghiên cứu'. (A) finding số ít, (C) find động từ, (D) found quá khứ.\nDịch: Bài báo khoa học cho biết các kết quả nghiên cứu của nhóm là bằng chứng xác nhận hiệu quả của thuốc."},{"n":119,"q":"The shopping center project was not as ------- to new investors as the planners had expected.","opts":["attracts","attract","attractive","attractively"],"ans":"C","xp":"Từ loại. Sau 'was not as' cần tính từ làm bổ ngữ cho chủ ngữ (be + tính từ) → (C) attractive 'hấp dẫn'. (A)(B) động từ, (D) trạng từ.\nDịch: Dự án trung tâm mua sắm không hấp dẫn các nhà đầu tư mới như những người lập kế hoạch đã kỳ vọng."},{"n":120,"q":"Ms. Ooshima went on a business trip to Singapore unexpectedly, so she had to ------- some of her tasks to her subordinates.","opts":["delegate","complete","invest","reply"],"ans":"A","xp":"Từ vựng (động từ). '------- some of her tasks to her subordinates' = ... công việc cho cấp dưới → (A) delegate 'giao, ủy thác'. delegate sth to sb. (B) complete 'hoàn thành', (C) invest 'đầu tư', (D) reply 'trả lời' (reply to).\nDịch: Cô Ooshima bất ngờ đi công tác Singapore nên cô phải giao một số công việc cho cấp dưới."},{"n":121,"q":"The security guard refused Mr. Dillon ------- because he could not provide a valid employee badge.","opts":["admits","admittedly","admittance","admitting"],"ans":"C","xp":"Từ loại. 'refused + sb + danh từ' (từ chối cho ai cái gì) → cần danh từ (C) admittance 'sự cho vào'. (A) động từ, (B) trạng từ 'phải thừa nhận', (D) V-ing.\nDịch: Nhân viên bảo vệ từ chối cho ông Dillon vào vì ông không xuất trình được thẻ nhân viên hợp lệ."},{"n":122,"q":"------- Top Gardening changed the checkout procedure on its Web site, its online sales have gone up dramatically.","opts":["Why","Since","Whether","Still"],"ans":"B","xp":"Liên từ. Mệnh đề sau ở thì hiện tại hoàn thành 'have gone up' → (B) Since 'kể từ khi' (since + quá khứ, hiện tại hoàn thành). (A) Why, (C) Whether không hợp nghĩa; (D) Still là trạng từ.\nDịch: Kể từ khi Top Gardening thay đổi quy trình thanh toán trên trang web, doanh số bán hàng trực tuyến đã tăng mạnh."},{"n":123,"q":"------- the bank transfer be made after 5 P.M., you can expect it to be processed the following working day.","opts":["As much as","Should","Everything","Whenever"],"ans":"B","xp":"Đảo ngữ câu điều kiện. 'Should + S + V nguyên mẫu' = If S should V → (B) Should. Câu có 'be made' (động từ nguyên mẫu) nên chỉ Should hợp ngữ pháp. (A) As much as, (C) Everything, (D) Whenever không đi với 'be made'.\nDịch: Nếu việc chuyển khoản được thực hiện sau 5 giờ chiều, bạn có thể tin rằng nó sẽ được xử lý vào ngày làm việc tiếp theo."},{"n":124,"q":"With the recent complaints of safety violations, Colbert Airlines will probably have ------- passengers than usual.","opts":["fewer","longer","each","neither"],"ans":"A","xp":"So sánh hơn. Có 'than usual' → cần dạng so sánh hơn; danh từ 'passengers' đếm được → (A) fewer 'ít hơn'. (B) longer 'dài hơn' không hợp nghĩa, (C) each, (D) neither không dùng với than.\nDịch: Với những lời phàn nàn gần đây về vi phạm an toàn, hãng hàng không Colbert có lẽ sẽ có ít hành khách hơn thường lệ."},{"n":125,"q":"The files will be deleted -------, so please confirm that you do not need them before selecting this action.","opts":["favorably","substantially","permanently","forcefully"],"ans":"C","xp":"Từ vựng (trạng từ). 'be deleted -------' + phải xác nhận trước khi xóa → (C) permanently 'vĩnh viễn'. (A) favorably 'thuận lợi', (B) substantially 'đáng kể', (D) forcefully 'mạnh mẽ'.\nDịch: Các tệp sẽ bị xóa vĩnh viễn, vì vậy vui lòng xác nhận bạn không cần chúng trước khi chọn thao tác này."},{"n":126,"q":"Marquee Couriers increased the hourly wage for delivery drivers ------- fill the positions more quickly.","opts":["in order to","similarly","moreover","in any case"],"ans":"A","xp":"Chỉ mục đích. Sau chỗ trống là động từ nguyên mẫu 'fill' → (A) in order to 'để'. (B) similarly 'tương tự', (C) moreover 'hơn nữa', (D) in any case 'dù sao đi nữa' không đi với V nguyên mẫu.\nDịch: Marquee Couriers đã tăng lương theo giờ cho tài xế giao hàng để tuyển người vào các vị trí nhanh hơn."},{"n":127,"q":"The airline representative apologized for the cancellation but explained that it was due to factors ------- the company's control.","opts":["between","against","throughout","beyond"],"ans":"D","xp":"Giới từ. 'factors ------- the company's control' → (D) beyond 'ngoài tầm' (beyond one's control = ngoài tầm kiểm soát). (A) between 'giữa', (B) against 'chống lại', (C) throughout 'khắp'.\nDịch: Đại diện hãng hàng không xin lỗi về việc hủy chuyến nhưng giải thích rằng đó là do các yếu tố nằm ngoài tầm kiểm soát của công ty."},{"n":128,"q":"By the end of the year, the state's health department ------- over five thousand restaurants to check for food safety violations.","opts":["has inspected","will have inspected","will be inspected","has been inspected"],"ans":"B","xp":"Thì động từ. 'By the end of the year' (mốc tương lai) → thì tương lai hoàn thành, chủ động vì có tân ngữ 'over five thousand restaurants' → (B) will have inspected. (C)(D) bị động, (A) hiện tại hoàn thành.\nDịch: Đến cuối năm, sở y tế của bang sẽ kiểm tra được hơn năm nghìn nhà hàng để phát hiện vi phạm an toàn thực phẩm."},{"n":129,"q":"During his keynote speech, Dr. Grayson ------- the role of nonprofit organizations in reducing poverty worldwide.","opts":["emphasized","assumed","hesitated","conserved"],"ans":"A","xp":"Từ vựng (động từ). Trong bài phát biểu, tiến sĩ ... vai trò của tổ chức phi lợi nhuận → (A) emphasized 'nhấn mạnh'. (B) assumed 'giả định', (C) hesitated 'do dự' (nội động từ), (D) conserved 'bảo tồn'.\nDịch: Trong bài phát biểu chính, tiến sĩ Grayson đã nhấn mạnh vai trò của các tổ chức phi lợi nhuận trong việc giảm nghèo trên toàn thế giới."},{"n":130,"q":"The Grand Villa neighborhood is known for having the city's largest ------- of high-end boutiques.","opts":["mobilization","concentration","recipient","commodity"],"ans":"B","xp":"Từ vựng (danh từ). 'the city's largest ------- of high-end boutiques' = nơi tập trung nhiều cửa hàng cao cấp nhất → (B) concentration 'sự tập trung'. (A) mobilization 'sự huy động', (C) recipient 'người nhận', (D) commodity 'hàng hóa'.\nDịch: Khu phố Grand Villa nổi tiếng là nơi tập trung nhiều cửa hàng thời trang cao cấp nhất thành phố."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following letter.","passage":"<p>November 16</p><p>Dear Ms. Charron,</p><p>It was a pleasure meeting you in person this morning to learn more about your desire to outsource Eastway Shipping's bookkeeping. <span class=\"blank\" data-n=\"131\">-------</span> I understand that you no longer wish to handle these types of tasks. I am confident that our dependable certified accountants can take on the <span class=\"blank\" data-n=\"132\">-------</span>. I hope that your questions and concerns <span class=\"blank\" data-n=\"133\">-------</span> during our meeting. If not, please feel free to contact me at 555-7966 with further inquiries. In addition, I have enclosed a brochure of our services for you to <span class=\"blank\" data-n=\"134\">-------</span>.</p><p>Warmest regards,<br>William Satterfield</p>","vi":"Ngày 16 tháng 11\n\nKính gửi bà Charron,\n\nRất vui được gặp trực tiếp bà sáng nay để tìm hiểu thêm về mong muốn thuê ngoài công việc kế toán sổ sách của Eastway Shipping. Nhu cầu kế toán của bà có thể dễ dàng được đội ngũ giàu kinh nghiệm của chúng tôi đảm nhận. Tôi hiểu rằng bà không còn muốn tự xử lý những loại công việc này nữa. Tôi tin chắc rằng các kế toán viên có chứng chỉ, đáng tin cậy của chúng tôi có thể đảm nhận vai trò này. Tôi hy vọng các câu hỏi và băn khoăn của bà đã được giải đáp trong buổi gặp. Nếu chưa, xin cứ liên hệ với tôi theo số 555-7966 để hỏi thêm. Ngoài ra, tôi có gửi kèm một tập giới thiệu dịch vụ của chúng tôi để bà xem qua.\n\nTrân trọng,\nWilliam Satterfield","qs":[{"n":131,"opts":["I will delete the error from the October invoice right away.","Please call my office if the items do not arrive on time.","Your accounting needs can easily be handled by our experienced team.","The business transports goods to distribution centers all over the world."],"ans":"C","xp":"Điền câu. Câu trước nói bà Charron muốn thuê ngoài việc kế toán (outsource bookkeeping), câu sau nói 'I understand that you no longer wish to handle these types of tasks' → câu (C) 'Nhu cầu kế toán của bà có thể dễ dàng được đội ngũ giàu kinh nghiệm của chúng tôi đảm nhận' nối mạch tự nhiên. (A) hóa đơn bị lỗi, (B) hàng giao trễ, (D) công ty vận chuyển hàng – không liên quan đến việc kế toán."},{"n":132,"opts":["incident","role","outcome","progress"],"ans":"B","xp":"Từ vựng. 'our accountants can take on the -------' → take on the role = đảm nhận vai trò → (B) role. (A) incident 'sự cố', (C) outcome 'kết quả', (D) progress 'tiến độ' không hợp."},{"n":133,"opts":["addresses","addressing","were addressed","had addressed"],"ans":"C","xp":"Thể bị động + thì. Chủ ngữ 'your questions and concerns' là đối tượng được giải đáp → bị động; sự việc xảy ra trong buổi gặp sáng nay (quá khứ) → (C) were addressed 'đã được giải đáp'. (A)(B)(D) đều là dạng chủ động."},{"n":134,"opts":["translate","review","recommend","oversee"],"ans":"B","xp":"Từ vựng. Gửi kèm tập giới thiệu dịch vụ 'for you to -------' → để bà xem qua → (B) review 'xem xét, xem qua'. (A) translate 'dịch', (C) recommend 'giới thiệu', (D) oversee 'giám sát' không hợp."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following press release.","passage":"<h3>Mercury Fashions Fall Line</h3><p>Mercury Fashions offers luxurious apparel that fits your lifestyle. On September 1, we <span class=\"blank\" data-n=\"135\">-------</span> our new line of fall fashions at a runway show at Sapphire Plaza. We closely follow the latest fashion trends, so we plan to have clothes dominated by the hottest colors to help you show your style. These cutting-edge designs are flattering to a wide range of body types. <span class=\"blank\" data-n=\"136\">-------</span>, we have new accessories like scarves, handbags, and hats that you can mix and match. <span class=\"blank\" data-n=\"137\">-------</span> Visit www.mercuryfashions.com for a sneak peek. These beautiful items will be in <span class=\"blank\" data-n=\"138\">-------</span> high-end department stores on the same day as the runway show.</p>","vi":"Bộ sưu tập mùa thu của Mercury Fashions\n\nMercury Fashions mang đến trang phục sang trọng phù hợp với phong cách sống của bạn. Vào ngày 1 tháng 9, chúng tôi sẽ ra mắt bộ sưu tập thời trang mùa thu mới tại một buổi trình diễn ở Sapphire Plaza. Chúng tôi luôn theo sát các xu hướng thời trang mới nhất, vì vậy chúng tôi dự định đưa ra những bộ trang phục với các gam màu được ưa chuộng nhất để giúp bạn thể hiện phong cách. Những thiết kế tiên phong này tôn dáng cho nhiều vóc dáng khác nhau. Ngoài ra, chúng tôi còn có phụ kiện mới như khăn quàng, túi xách và mũ mà bạn có thể phối với nhau. Hãy tạo ra hàng chục phong cách của riêng bạn tùy thích. Truy cập www.mercuryfashions.com để xem trước. Những món đồ đẹp này sẽ có mặt tại hầu hết các cửa hàng bách hóa cao cấp ngay trong ngày diễn ra buổi trình diễn.","qs":[{"n":135,"opts":["have revealed","have been revealing","are going to reveal","revealed"],"ans":"C","xp":"Thì động từ. Thông cáo báo chí giới thiệu sự kiện sắp diễn ra; câu cuối 'These beautiful items will be in ... stores on the same day as the runway show' (tương lai) → buổi trình diễn chưa diễn ra → (C) are going to reveal 'sẽ ra mắt'. (A)(B) hiện tại hoàn thành, (D) quá khứ."},{"n":136,"opts":["Even","Also","Rather","Merely"],"ans":"B","xp":"Trạng từ liên kết. Câu trước nói về thiết kế quần áo, câu này thêm thông tin về phụ kiện mới → (B) Also 'Ngoài ra, cũng'. (A) Even 'thậm chí', (C) Rather 'đúng hơn là', (D) Merely 'chỉ' không hợp."},{"n":137,"opts":["Our design team is always standing by you to meet your custom requests.","The tags should be removed before wearing them.","Create dozens of your own looks as you want.","Our headquarters will relocate in the city of New York."],"ans":"C","xp":"Điền câu. Câu trước: phụ kiện 'that you can mix and match' (có thể phối với nhau) → (C) 'Hãy tạo ra hàng chục phong cách của riêng bạn tùy thích' tiếp nối ý phối đồ. (A) nhận đặt may riêng, (B) tháo nhãn mác, (D) chuyển trụ sở – không liên quan."},{"n":138,"opts":["most","which","their","soon"],"ans":"A","xp":"Từ hạn định. Trước cụm danh từ số nhiều 'high-end department stores' → (A) most 'hầu hết'. (B) which là đại từ quan hệ, (C) their 'của họ' không có đối tượng phù hợp, (D) soon là trạng từ."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following letter.","passage":"<p>October 9</p><p>Ralph Benton<br>874 Everette Way<br>Coral Springs, FL 33065</p><p>Dear Mr. Benton,</p><p>Thanks to the collaborative <span class=\"blank\" data-n=\"139\">-------</span> of you and your team, Otis Rentals has become the number one car rental agency in Florida. Our market share has grown from 15% to 41% in just three years under your leadership. <span class=\"blank\" data-n=\"140\">-------</span></p><p>On behalf of Otis Rentals, I would like to invite you to transfer to our Texas branch, where you would take on the role of regional manager. This region <span class=\"blank\" data-n=\"141\">-------</span> the most competitive one in the country, but I believe that you are up to the challenge. The preferred start date is November 15. <span class=\"blank\" data-n=\"142\">-------</span>, we can be somewhat flexible if more time to make arrangements is needed.</p><p>Sincerely,<br>Lucille Walsh, Chief Operations Officer<br>Otis Rentals</p>","vi":"Ngày 9 tháng 10\n\nRalph Benton\n874 Everette Way\nCoral Springs, FL 33065\n\nKính gửi ông Benton,\n\nNhờ nỗ lực hợp tác của ông và nhóm của ông, Otis Rentals đã trở thành công ty cho thuê xe số một ở Florida. Thị phần của chúng ta đã tăng từ 15% lên 41% chỉ trong ba năm dưới sự lãnh đạo của ông. Thành tích như vậy hiếm khi thấy trong ngành của chúng ta.\n\nThay mặt Otis Rentals, tôi muốn mời ông chuyển sang chi nhánh Texas, nơi ông sẽ đảm nhận vai trò quản lý khu vực. Khu vực này được xem là khu vực cạnh tranh nhất cả nước, nhưng tôi tin rằng ông đủ sức đương đầu với thử thách. Ngày bắt đầu mong muốn là 15 tháng 11. Tuy nhiên, chúng tôi có thể linh động phần nào nếu ông cần thêm thời gian để thu xếp.\n\nTrân trọng,\nLucille Walsh, Giám đốc Vận hành\nOtis Rentals","qs":[{"n":139,"opts":["efforts","reports","panels","visits"],"ans":"A","xp":"Từ vựng. 'Thanks to the collaborative ------- of you and your team' → nhờ những nỗ lực hợp tác → (A) efforts 'nỗ lực'. (B) reports 'báo cáo', (C) panels 'hội đồng', (D) visits 'chuyến thăm' không hợp nghĩa."},{"n":140,"opts":["I will take a trip to Florida for the first time.","Such an accomplishment is rarely seen in our field.","Please confirm which job candidate you prefer.","It had four doors and a spacious trunk in the back."],"ans":"B","xp":"Điền câu. Câu trước nêu thành tích: thị phần tăng từ 15% lên 41% trong 3 năm → (B) 'Thành tích như vậy hiếm khi thấy trong ngành của chúng ta' – 'Such an accomplishment' thay cho thành tích vừa nêu. (A) ông Benton đang ở Florida rồi, (C) ứng viên, (D) mô tả chiếc xe – không hợp."},{"n":141,"opts":["considers","was considered","is considered","considering"],"ans":"C","xp":"Thể bị động + thì. 'This region ------- the most competitive one' = khu vực này được xem là cạnh tranh nhất → bị động; đang nói về hiện tại (vế sau 'I believe that you are') → (C) is considered. (A) chủ động, (B) quá khứ, (D) V-ing không làm động từ chính."},{"n":142,"opts":["Consequently","Besides","For example","However"],"ans":"D","xp":"Trạng từ liên kết. Câu trước: ngày bắt đầu mong muốn là 15/11; câu sau: có thể linh động nếu cần thêm thời gian → ý tương phản → (D) However 'tuy nhiên'. (A) Consequently 'do đó', (B) Besides 'ngoài ra', (C) For example 'ví dụ'."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following article.","passage":"<p>(October 12)—Rapid Insurance, one of the nation's largest providers of homeowners insurance, has announced a change at the executive level. Lillian Howes has been selected by the Rapid Insurance board as the company's new CEO. She <span class=\"blank\" data-n=\"143\">-------</span> James Loftin, who held the position for thirteen years.</p><p>\"Mr. Loftin will leave the company to work in the charity sector, and we wish him all the best in his <span class=\"blank\" data-n=\"144\">-------</span> endeavors,\" said Rapid Insurance spokesperson Anna Gilley. Investors are pleased with the change, as Ms. Howes is no stranger to Rapid Insurance's operations. \"Ms. Howes <span class=\"blank\" data-n=\"145\">-------</span> worked as the managing director of the company before becoming the chief operating officer three years ago,\" commented Ms. Gilley. \"<span class=\"blank\" data-n=\"146\">-------</span>\"</p>","vi":"(12 tháng 10) – Rapid Insurance, một trong những công ty bảo hiểm nhà ở lớn nhất cả nước, đã công bố thay đổi ở cấp điều hành. Bà Lillian Howes đã được hội đồng quản trị Rapid Insurance chọn làm giám đốc điều hành (CEO) mới của công ty. Bà kế nhiệm ông James Loftin, người đã giữ vị trí này trong mười ba năm.\n\n\"Ông Loftin sẽ rời công ty để làm việc trong lĩnh vực từ thiện, và chúng tôi chúc ông mọi điều tốt đẹp nhất trong những dự định sắp tới,\" người phát ngôn của Rapid Insurance, bà Anna Gilley cho biết. Các nhà đầu tư hài lòng với sự thay đổi này, vì bà Howes không hề xa lạ với hoạt động của Rapid Insurance. \"Trước đây bà Howes từng làm giám đốc quản lý của công ty trước khi trở thành giám đốc vận hành ba năm trước,\" bà Gilley nhận xét. \"Chúng tôi tin rằng quá trình chuyển giao sẽ diễn ra suôn sẻ.\"","qs":[{"n":143,"opts":["has been succeeded","succeeds","would have succeeded","was succeeding"],"ans":"B","xp":"Thì + thể. succeed sb = kế nhiệm ai. Bà Howes (chủ ngữ) kế nhiệm ông Loftin (tân ngữ) → chủ động; nói về sự thay đổi hiện tại → (B) succeeds. (A) bị động, (C) giả định quá khứ, (D) quá khứ tiếp diễn không hợp."},{"n":144,"opts":["constant","accurate","future","distant"],"ans":"C","xp":"Từ vựng (tính từ). Ông Loftin sắp rời công ty để làm từ thiện → chúc ông thành công trong những dự định 'tương lai' → (C) future. (A) constant 'liên tục', (B) accurate 'chính xác', (D) distant 'xa xôi'."},{"n":145,"opts":["authentically","suddenly","regrettably","previously"],"ans":"D","xp":"Từ vựng (trạng từ). '------- worked as the managing director ... before becoming the COO three years ago' → việc đã làm từ trước → (D) previously 'trước đây'. (A) authentically 'thật sự', (B) suddenly 'đột ngột', (C) regrettably 'đáng tiếc'."},{"n":146,"opts":["We plan to look into the matter carefully.","We believe the transition will be a smooth one.","The new insurance package has become popular.","The board will make the final decision soon."],"ans":"B","xp":"Điền câu. Đoạn văn nói bà Howes rất quen thuộc với hoạt động công ty, nhà đầu tư hài lòng → (B) 'Chúng tôi tin quá trình chuyển giao sẽ suôn sẻ' kết luận hợp lý. (A) điều tra sự việc, (C) gói bảo hiểm mới – lạc đề; (D) hội đồng đã chọn bà Howes rồi nên không còn 'sắp quyết định'."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following information.","passages":["<h3>Excitement and thrills are just around the corner!</h3><p>Director Nick Murray revealed in a recent interview that the sequel to the popular <i>The Warrant</i> is coming out on July 29. The movie, called <i>The Warrant 2: Deadly Search</i>, stars Eric Jackson and will be playing in theaters nationwide.</p><p>Baxter Theater is holding a special promotion for the movie. Book your ticket at www.baxter99.com by July 20, and you'll be sent a voucher to download one of the eighteen songs from <i>The Warrant 2</i>'s soundtrack.</p>"],"vi":"Hồi hộp và gay cấn đang đến rất gần!\n\nĐạo diễn Nick Murray tiết lộ trong một cuộc phỏng vấn gần đây rằng phần tiếp theo của bộ phim nổi tiếng The Warrant sẽ ra mắt vào ngày 29 tháng 7. Bộ phim mang tên The Warrant 2: Deadly Search, do Eric Jackson đóng vai chính, sẽ được chiếu tại các rạp trên toàn quốc.\n\nRạp Baxter đang tổ chức chương trình khuyến mãi đặc biệt cho bộ phim. Hãy đặt vé tại www.baxter99.com trước ngày 20 tháng 7, bạn sẽ được gửi một phiếu để tải về một trong mười tám bài hát trong nhạc phim The Warrant 2.","qs":[{"n":147,"q":"According to the information, what will happen on July 29?","qvi":"Theo thông tin, điều gì sẽ xảy ra vào ngày 29 tháng 7?","opts":["A celebrity will be interviewed.","A price will decrease.","A theater will have a grand opening.","A film will debut."],"ans":"D","xp":"Câu hỏi chi tiết. 'the sequel to the popular The Warrant is coming out on July 29' → phim mới ra mắt ngày 29/7 → (D). 'coming out' = debut (ra mắt).\n(A) Một người nổi tiếng sẽ được phỏng vấn. (B) Giá sẽ giảm. (C) Một rạp chiếu sẽ khai trương. (D) Một bộ phim sẽ ra mắt."},{"n":148,"q":"How can a free music voucher be obtained?","qvi":"Làm thế nào để nhận được phiếu tải nhạc miễn phí?","opts":["By purchasing tickets for a group","By completing a survey","By making an online reservation","By arriving at a site early"],"ans":"C","xp":"Câu hỏi chi tiết. 'Book your ticket at www.baxter99.com by July 20, and you'll be sent a voucher' → đặt vé qua trang web = đặt chỗ trực tuyến → (C).\n(A) Mua vé cho nhóm (B) Hoàn thành khảo sát (C) Đặt vé trực tuyến (D) Đến địa điểm sớm"}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> All Employees &lt;staff@cahaltravel.com&gt;</p><p><b>From:</b> Vadim Bodrova &lt;v.bodrova@cahaltravel.com&gt;</p><p><b>Date:</b> December 18</p><p><b>Subject:</b> Repeat business</p></div><p>As we discussed in the staff meeting, Cahal Travel is looking for ways to increase the percentage of customers who book more than one trip with us. Currently, we annually contact customers who have booked an international trip with us to introduce packages they may be interested in. Starting from next week, we will send them information about tour packages once every four months. Please see below an example of a real customer entry for your reference.</p><table><tr><th>Current</th><th>New</th></tr><tr><td>Name: CUSTOMER NAME</td><td>Name: Henrik Hetland</td></tr><tr><td>Phone: PHONE NUMBER</td><td>Phone: 649-555-3328</td></tr><tr><td>E-mail address: E-MAIL ADDRESS</td><td>E-mail address: hhetland@broadmoorinc.net</td></tr><tr><td>Destination(s): PREVIOUS TRAVEL SITES</td><td>Destination(s): Tokyo, Japan; Santiago, Chile</td></tr><tr><td>Contact: PREFERRED FORM OF CONTACT</td><td>Contact: E-mail</td></tr><tr><td></td><td>Last Contact: December 2</td></tr></table><p>I'm happy to answer any questions you may have about the new procedure.</p><p>Thank you!<br>Vadim Bodrova<br>Cahal Travel</p>"],"vi":"Người nhận: Toàn thể nhân viên\nNgười gửi: Vadim Bodrova\nNgày: 18 tháng 12\nTiêu đề: Khách hàng quay lại\n\nNhư đã bàn trong cuộc họp nhân viên, Cahal Travel đang tìm cách tăng tỷ lệ khách hàng đặt nhiều hơn một chuyến đi với chúng ta. Hiện tại, mỗi năm một lần chúng ta liên hệ với những khách đã đặt chuyến đi quốc tế để giới thiệu các gói tour họ có thể quan tâm. Bắt đầu từ tuần sau, chúng ta sẽ gửi thông tin về các gói tour cho họ bốn tháng một lần. Vui lòng xem bên dưới ví dụ về hồ sơ của một khách hàng thật để tham khảo.\n\nMẫu hiện tại / Mẫu mới: Tên – Henrik Hetland; Điện thoại – 649-555-3328; E-mail – hhetland@broadmoorinc.net; Điểm đến – Tokyo, Nhật Bản; Santiago, Chile; Cách liên hệ – E-mail; Lần liên hệ gần nhất – 2 tháng 12.\n\nTôi sẵn lòng giải đáp mọi thắc mắc về quy trình mới.\n\nCảm ơn!\nVadim Bodrova\nCahal Travel","qs":[{"n":149,"q":"What will the business change?","qvi":"Doanh nghiệp sẽ thay đổi điều gì?","opts":["The processing fee for booking a trip","The size of the groups for tour packages","The frequency of contacting past customers","The requirements for new vacation planners"],"ans":"C","xp":"Câu hỏi chi tiết. 'Currently, we annually contact customers... Starting from next week, we will send them information... once every four months' → từ mỗi năm một lần thành 4 tháng một lần = thay đổi tần suất liên hệ khách cũ → (C).\n(A) Phí xử lý đặt chuyến (B) Quy mô đoàn tour (C) Tần suất liên hệ khách hàng cũ (D) Yêu cầu đối với người lập kế hoạch kỳ nghỉ mới"},{"n":150,"q":"Who most likely is Mr. Hetland?","qvi":"Ông Hetland nhiều khả năng là ai?","opts":["A job candidate","A travel agent","An airline employee","An overseas traveler"],"ans":"D","xp":"Câu hỏi suy luận. Ông Hetland là ví dụ 'a real customer entry', điểm đến là 'Tokyo, Japan; Santiago, Chile', và công ty liên hệ khách 'who have booked an international trip' → ông là khách du lịch nước ngoài → (D).\n(A) Ứng viên xin việc (B) Nhân viên đại lý du lịch (C) Nhân viên hãng hàng không (D) Khách du lịch nước ngoài"}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Stewart Bowser [9:24 A.M.]</b></p><p>Do you have a minute? I'm trying to reserve a time slot for Joseph Harris to have a checkup with Dr. Pritchard, but there is a problem. It looks like he has been entered into the system twice. I'm not sure which file to use.</p></div><div class=\"msg\"><p><b>Delilah Gibbs [9:25 A.M.]</b></p><p>That sometimes happens if someone inputs new patient information without saving the changes properly. However, there could also be two people with the same name.</p></div><div class=\"msg\"><p><b>Stewart Bowser [9:26 A.M.]</b></p><p>Good point. How can I tell if that's the case?</p></div><div class=\"msg\"><p><b>Delilah Gibbs [9:27 A.M.]</b></p><p>Look at the birth date to confirm the patient's identity. Then you'll know whether or not you have the right one.</p></div><div class=\"msg\"><p><b>Stewart Bowser [9:28 A.M.]</b></p><p>Of course! Thank you!</p></div>"],"vi":"Stewart Bowser [9:24]: Chị có rảnh một phút không? Tôi đang cố đặt lịch cho Joseph Harris khám sức khỏe với bác sĩ Pritchard nhưng gặp vấn đề. Có vẻ như ông ấy đã bị nhập vào hệ thống hai lần. Tôi không chắc nên dùng hồ sơ nào.\nDelilah Gibbs [9:25]: Chuyện đó đôi khi xảy ra nếu ai đó nhập thông tin bệnh nhân mới mà không lưu thay đổi đúng cách. Tuy nhiên, cũng có thể có hai người trùng tên.\nStewart Bowser [9:26]: Đúng thật. Làm sao tôi biết có phải như vậy không?\nDelilah Gibbs [9:27]: Hãy xem ngày sinh để xác nhận danh tính bệnh nhân. Khi đó anh sẽ biết mình có chọn đúng người hay không.\nStewart Bowser [9:28]: Tất nhiên rồi! Cảm ơn chị!","qs":[{"n":151,"q":"What is Mr. Bowser trying to do?","qvi":"Ông Bowser đang cố làm gì?","opts":["Change an address","Make an appointment","Bill a patient","Contact a doctor"],"ans":"B","xp":"Câu hỏi chi tiết. 'I'm trying to reserve a time slot for Joseph Harris to have a checkup with Dr. Pritchard' → đặt lịch khám = make an appointment → (B).\n(A) Đổi địa chỉ (B) Đặt lịch hẹn (C) Gửi hóa đơn cho bệnh nhân (D) Liên hệ bác sĩ"},{"n":152,"q":"At 9:28 A.M., what does Mr. Bowser most likely mean when he writes, \"Of course\"?","qvi":"Lúc 9:28, ông Bowser có ý gì khi viết \"Of course\"?","opts":["He knows a patient personally.","A computer is working fine.","He is willing to help Ms. Gibbs.","A solution is obvious."],"ans":"D","xp":"Câu hỏi hàm ý. Bà Gibbs chỉ cách: 'Look at the birth date to confirm the patient's identity.' Ông Bowser đáp 'Of course!' = à đúng rồi, cách đó quá rõ ràng → (D) giải pháp rất hiển nhiên.\n(A) Ông quen biết bệnh nhân (B) Máy tính hoạt động tốt (C) Ông sẵn lòng giúp bà Gibbs (D) Giải pháp rất rõ ràng"}]},{"ns":[153,155],"head":"Questions 153-155 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Hans Edgren &lt;h.edgren@lincoya.com&gt;</p><p><b>From:</b> Amherst Bank &lt;accounts@amherstbank.com&gt;</p><p><b>Date:</b> December 9</p><p><b>Subject:</b> Amherst Bank Credit Card</p></div><p>Dear Mr. Edgren,</p><p>I am writing to inform you that the limit on your Amherst Bank credit card has been raised from $1,800 to $2,500. <span class=\"pos\">[1]</span> We are taking this action because you have had no late payments on your account for the past year. Your account's interest rate will also be lowered by two percent. <span class=\"pos\">[2]</span></p><p>If you are satisfied with these conditions, your service contract will be automatically updated, and no further action is needed. However, should you wish to return to the previous credit limit and interest rate, please inform the bank by calling 1-800-555-7799. <span class=\"pos\">[3]</span> Thank you for being an Amherst Bank customer. <span class=\"pos\">[4]</span></p><p>Sincerely,<br>Benjamin Elliot<br>Account Services, Amherst Bank</p>"],"vi":"Kính gửi ông Edgren,\n\nTôi viết thư này để thông báo rằng hạn mức thẻ tín dụng Amherst Bank của ông đã được nâng từ 1.800 đô la lên 2.500 đô la. Chúng tôi thực hiện điều này vì ông không có khoản thanh toán trễ nào trong năm qua. Lãi suất tài khoản của ông cũng sẽ được giảm hai phần trăm.\n\nNếu ông hài lòng với các điều kiện này, hợp đồng dịch vụ của ông sẽ được tự động cập nhật và ông không cần làm gì thêm. Tuy nhiên, nếu ông muốn quay lại hạn mức và lãi suất trước đây, vui lòng báo cho ngân hàng bằng cách gọi 1-800-555-7799. Xác nhận yêu cầu của ông sau đó sẽ được gửi qua e-mail. Cảm ơn ông đã là khách hàng của Amherst Bank.\n\nTrân trọng,\nBenjamin Elliot\nBộ phận Dịch vụ Tài khoản, Amherst Bank","qs":[{"n":153,"q":"Why did Mr. Elliot send the e-mail to Mr. Edgren?","qvi":"Tại sao ông Elliot gửi e-mail cho ông Edgren?","opts":["To check some unusual activity on a credit card","To remind him that a credit limit has been reached","To notify him of account changes on his credit card","To ask him to pay the monthly bill on his account"],"ans":"C","xp":"Câu hỏi mục đích. 'I am writing to inform you that the limit on your ... credit card has been raised' + lãi suất giảm 2% → thông báo thay đổi tài khoản thẻ → (C).\n(A) Kiểm tra giao dịch bất thường (B) Nhắc đã chạm hạn mức (C) Thông báo thay đổi tài khoản thẻ tín dụng (D) Yêu cầu trả hóa đơn tháng"},{"n":154,"q":"What is Mr. Edgren asked to do?","qvi":"Ông Edgren được yêu cầu làm gì?","opts":["Contact the company if he wants to reset some terms","Update his billing address on the account","Verify that he approved some recent purchases","Provide a reason for making a late payment"],"ans":"A","xp":"Câu hỏi chi tiết. 'should you wish to return to the previous credit limit and interest rate, please inform the bank by calling...' → liên hệ ngân hàng nếu muốn đặt lại điều khoản cũ → (A).\n(A) Liên hệ công ty nếu muốn đặt lại một số điều khoản (B) Cập nhật địa chỉ thanh toán (C) Xác nhận các giao dịch gần đây (D) Giải thích lý do trả trễ"},{"n":155,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"Confirmation of your request will then be sent by e-mail.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào: \"Xác nhận yêu cầu của ông sau đó sẽ được gửi qua e-mail.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Điền câu. 'your request' và 'then' cho thấy câu phải đứng sau một hành động yêu cầu: 'please inform the bank by calling 1-800-555-7799. [3]' → gọi điện yêu cầu, sau đó nhận xác nhận qua e-mail → (C)."}]},{"ns":[156,157],"head":"Questions 156-157 refer to the following memo.","passages":["<div class=\"hdr\"><p><b>To:</b> All Magnolia Advisors Staff</p><p><b>From:</b> Kwang-min Hwang</p><p><b>Date:</b> October 24</p><p><b>Subject:</b> Financial data</p></div><p>Magnolia Advisors is responsible for an increasing amount of sensitive financial data from our clients. Because of this, the executive committee has decided to make changes to improve the protection of confidential files and prevent unauthorized access. On November 6, card readers will be installed on the doors of all file storage rooms, and employees will be issued key cards. In addition to denying entry to those without cards, the card readers will keep a record of who is entering the room and when. If a card reader malfunctions, please see Maintenance Director Jim Abbott in his office. Should you have questions or concerns about the change, feel free to call me at extension 23.</p>"],"vi":"Magnolia Advisors chịu trách nhiệm về lượng dữ liệu tài chính nhạy cảm ngày càng lớn của khách hàng. Vì vậy, ban điều hành đã quyết định thực hiện các thay đổi để tăng cường bảo vệ hồ sơ mật và ngăn chặn truy cập trái phép. Vào ngày 6 tháng 11, đầu đọc thẻ sẽ được lắp trên cửa của tất cả các phòng lưu trữ hồ sơ, và nhân viên sẽ được cấp thẻ từ. Ngoài việc không cho người không có thẻ vào, đầu đọc thẻ còn ghi lại ai vào phòng và vào lúc nào. Nếu đầu đọc thẻ bị trục trặc, vui lòng gặp Giám đốc Bảo trì Jim Abbott tại văn phòng của ông. Nếu có thắc mắc hay băn khoăn về thay đổi này, cứ gọi cho tôi theo số máy lẻ 23.","qs":[{"n":156,"q":"What is the purpose of the memo?","qvi":"Mục đích của bản ghi nhớ là gì?","opts":["To describe computer software that stores digital files","To notify employees of increased security measures","To congratulate the staff on meeting a financial goal","To introduce a new policy regarding client interactions"],"ans":"B","xp":"Câu hỏi mục đích. 'make changes to improve the protection of confidential files and prevent unauthorized access... card readers will be installed' → thông báo biện pháp an ninh được tăng cường → (B).\n(A) Mô tả phần mềm lưu tệp (B) Thông báo biện pháp an ninh tăng cường (C) Chúc mừng đạt mục tiêu tài chính (D) Giới thiệu chính sách giao tiếp với khách hàng"},{"n":157,"q":"What does Mr. Hwang recommend doing if a device is not working?","qvi":"Ông Hwang khuyên làm gì nếu thiết bị không hoạt động?","opts":["Visiting a maintenance employee","Reporting a problem by e-mail","Calling him at his office","Ordering some replacement equipment"],"ans":"A","xp":"Câu hỏi chi tiết. 'If a card reader malfunctions, please see Maintenance Director Jim Abbott in his office' → đến gặp nhân viên bảo trì → (A). 'malfunctions' = not working.\n(A) Đến gặp nhân viên bảo trì (B) Báo lỗi qua e-mail (C) Gọi ông Hwang tại văn phòng (D) Đặt mua thiết bị thay thế"}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Ellie Jarvis &lt;elliejarvis@boylestoninc.com&gt;</p><p><b>From:</b> GTP Cleaning &lt;info@gtpcleaning.com&gt;</p><p><b>Date:</b> January 19</p><p><b>Subject:</b> Order #49025</p></div><p>Dear Ms. Jarvis,</p><p>On behalf of GTP Cleaning, I would like to apologize for an issue with your order (#49025) that has put its delivery behind schedule.</p><p>The following products are in stock and will be dispatched today, arriving at your mailing address within 2-3 days:</p><ul><li>Brightex Wood Polish, 9.7-oz. canister</li><li>McGraw All-Purpose Cleaner, 32-oz. bottle</li><li>Trumbull Scouring Pads, pack of 6</li><li>Avery Window Cleaner, 26-oz. bottle, new non-toxic formula</li></ul><p>The following item is currently out of stock:</p><ul><li>Freida Pod, pack of 3 2.5-oz. air-freshener units, Cherry Blossom fragrance</li></ul><p>We will not receive replacements for the out-of-stock item at our warehouse for 4 to 6 weeks. If you take no action, this item will be shipped as soon as it becomes available again. There will be no additional charge for the separate shipment. Please note that there are variations of the same air-freshener, such as Calming Lavender and French Vanilla. Please click here to check out the complete list on our Web site, as you may find something you prefer. If so, you can adjust the order in your account anytime before the final item is shipped.</p><p>Thank you for your patronage!</p><p>Leon Espinoza<br>GTP Cleaning</p>"],"vi":"Kính gửi bà Jarvis,\n\nThay mặt GTP Cleaning, tôi xin lỗi về sự cố với đơn hàng của bà (#49025) khiến việc giao hàng bị chậm so với kế hoạch.\n\nCác sản phẩm sau còn hàng và sẽ được gửi đi hôm nay, đến địa chỉ của bà trong vòng 2-3 ngày: dầu đánh bóng gỗ Brightex (hộp 9,7 oz), nước lau đa năng McGraw (chai 32 oz), miếng cọ rửa Trumbull (gói 6 miếng), nước lau kính Avery (chai 26 oz, công thức mới không độc hại).\n\nSản phẩm sau hiện đang hết hàng: Freida Pod, gói 3 viên làm thơm phòng 2,5 oz, hương Hoa Anh Đào.\n\nKho của chúng tôi sẽ chưa nhận được hàng bổ sung cho sản phẩm hết hàng trong 4 đến 6 tuần. Nếu bà không làm gì, sản phẩm này sẽ được gửi ngay khi có hàng trở lại. Sẽ không tính thêm phí cho lần gửi riêng này. Xin lưu ý có những phiên bản khác của cùng loại sản phẩm làm thơm phòng, như Oải Hương Dịu Nhẹ và Vani Pháp. Vui lòng bấm vào đây để xem danh sách đầy đủ trên trang web của chúng tôi, biết đâu bà sẽ tìm được loại mình thích hơn. Nếu vậy, bà có thể điều chỉnh đơn hàng trong tài khoản bất cứ lúc nào trước khi sản phẩm cuối cùng được gửi đi.\n\nCảm ơn bà đã ủng hộ!\nLeon Espinoza\nGTP Cleaning","qs":[{"n":158,"q":"Why was the e-mail sent?","qvi":"Tại sao e-mail được gửi?","opts":["To offer a refund","To approve a request","To explain a delay","To promote a product"],"ans":"C","xp":"Câu hỏi mục đích. 'I would like to apologize for an issue with your order that has put its delivery behind schedule' → giải thích việc giao hàng bị chậm → (C).\n(A) Đề nghị hoàn tiền (B) Chấp thuận một yêu cầu (C) Giải thích sự chậm trễ (D) Quảng cáo sản phẩm"},{"n":159,"q":"What is mentioned about the Freida Pod?","qvi":"Điều gì được đề cập về Freida Pod?","opts":["It has been discontinued.","It is available in multiple scents.","It has non-toxic ingredients.","It is the most popular product."],"ans":"B","xp":"Câu hỏi chi tiết. 'there are variations of the same air-freshener, such as Calming Lavender and French Vanilla' (ngoài hương Cherry Blossom) → có nhiều mùi hương → (B). (A) sai vì chỉ tạm hết hàng; (C) 'non-toxic' là của Avery Window Cleaner.\n(A) Đã ngừng sản xuất (B) Có nhiều mùi hương (C) Có thành phần không độc hại (D) Là sản phẩm bán chạy nhất"},{"n":160,"q":"What does Mr. Espinoza ask Ms. Jarvis to do?","qvi":"Ông Espinoza đề nghị bà Jarvis làm gì?","opts":["View some alternative options online","Check the quantity of her order","Resend the payment for the current order","Provide feedback after testing a product"],"ans":"A","xp":"Câu hỏi chi tiết. 'Please click here to check out the complete list on our Web site, as you may find something you prefer' → xem các lựa chọn thay thế trên mạng → (A).\n(A) Xem các lựa chọn thay thế trên mạng (B) Kiểm tra số lượng đơn hàng (C) Thanh toán lại (D) Góp ý sau khi dùng thử"}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following article.","passages":["<h3>Cantrece Shopping Center Wins National Award</h3><p>March 22—Cantrece Shopping Center has been honored with the prestigious Conifer Prize in a ceremony held last night at the San Mateo Hotel. The award is presented annually to a company or organization whose building follows eco-friendly practices, uses sustainable building materials, and reduces energy consumption. The shopping center is an exemplary model for all of these categories. Solar panels on the building's rooftop supply over 80% of the building's needs. In addition, skylights reduce the need for daytime lighting, and a rainwater collection system provides water for flushing toilets and cleaning. The building's designer, Yolanda Knapp, was present to accept the award at the ceremony, and she said she and her colleagues will continue to strive to create functional structures that use resources responsibly.</p><p>The judging panel that selects the winner of the Conifer Prize is continually looking for companies that meet their criteria. If you would like to recommend a company to be considered for this prize, please visit www.coniferprize.com.</p>"],"vi":"Trung tâm mua sắm Cantrece giành giải thưởng quốc gia\n\n22 tháng 3 – Trung tâm mua sắm Cantrece đã được vinh danh với giải Conifer danh giá tại buổi lễ tổ chức tối qua ở khách sạn San Mateo. Giải thưởng được trao hằng năm cho một công ty hoặc tổ chức có tòa nhà áp dụng các biện pháp thân thiện với môi trường, sử dụng vật liệu xây dựng bền vững và giảm tiêu thụ năng lượng. Trung tâm mua sắm này là hình mẫu tiêu biểu ở tất cả các tiêu chí trên. Các tấm pin mặt trời trên mái cung cấp hơn 80% nhu cầu năng lượng của tòa nhà. Ngoài ra, cửa sổ mái giúp giảm nhu cầu chiếu sáng ban ngày, và hệ thống thu gom nước mưa cung cấp nước để xả bồn cầu và lau dọn. Người thiết kế tòa nhà, bà Yolanda Knapp, đã có mặt để nhận giải tại buổi lễ, và bà cho biết bà cùng các đồng nghiệp sẽ tiếp tục nỗ lực tạo ra những công trình hữu dụng, sử dụng tài nguyên có trách nhiệm.\n\nHội đồng giám khảo chọn người thắng giải Conifer luôn tìm kiếm các công ty đáp ứng tiêu chí. Nếu bạn muốn đề cử một công ty để được xem xét cho giải thưởng này, hãy truy cập www.coniferprize.com.","qs":[{"n":161,"q":"For what did the Cantrece Shopping Center receive an award?","qvi":"Trung tâm mua sắm Cantrece nhận giải nhờ điều gì?","opts":["Its environmentally friendly design","Its contributions to charity","Its unique products for sale","Its record number of customers"],"ans":"A","xp":"Câu hỏi chi tiết. Giải trao cho tòa nhà 'follows eco-friendly practices, uses sustainable building materials, and reduces energy consumption' + pin mặt trời, thu nước mưa → thiết kế thân thiện môi trường → (A).\n(A) Thiết kế thân thiện với môi trường (B) Đóng góp từ thiện (C) Sản phẩm độc đáo (D) Lượng khách kỷ lục"},{"n":162,"q":"Where does Ms. Knapp most likely work?","qvi":"Bà Knapp nhiều khả năng làm việc ở đâu?","opts":["At a magazine publisher","At a shopping center","At a real estate agency","At an architectural firm"],"ans":"D","xp":"Câu hỏi suy luận. 'The building's designer, Yolanda Knapp... she and her colleagues will continue to strive to create functional structures' → người thiết kế công trình → làm ở công ty kiến trúc → (D).\n(A) Nhà xuất bản tạp chí (B) Trung tâm mua sắm (C) Công ty bất động sản (D) Công ty kiến trúc"},{"n":163,"q":"According to the article, what can be done on the Web site?","qvi":"Theo bài báo, có thể làm gì trên trang web?","opts":["Downloading a list of selection criteria","Viewing photographs from previous winners","Nominating companies for future awards","Reading the interview with Ms. Knapp"],"ans":"C","xp":"Câu hỏi chi tiết. 'If you would like to recommend a company to be considered for this prize, please visit www.coniferprize.com' → đề cử công ty = nominating → (C).\n(A) Tải danh sách tiêu chí (B) Xem ảnh người thắng trước (C) Đề cử công ty cho giải sau (D) Đọc phỏng vấn bà Knapp"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Sylvia Reid &lt;s.reid@harringoninc.com&gt;</p><p><b>From:</b> Chris Alexander &lt;chris_alexander@modoccorp.com&gt;</p><p><b>Date:</b> February 19</p><p><b>Subject:</b> Modoc Corp.</p></div><p>Dear Ms. Reid,</p><p>It was a pleasure meeting you at the recent Cosmetics Retailers Trade Expo in San Francisco. As promised, I'm sending you the current catalog for Modoc Corp. <span class=\"pos\">[1]</span></p><p>I understand that you are looking for ways to boost sales in your shop, and I believe that our products can help you reach this goal. <span class=\"pos\">[2]</span> We have a variety of face creams, cleansers, and other skincare products. One of our best sellers is Meridian, a lightweight moisturizer that is intended for daily use. Customers love it because it is fragrance-free, so they don't have to worry about how it might combine with their perfume or other beauty products. <span class=\"pos\">[3]</span></p><p>Should you have any questions, I would be happy to answer them anytime. <span class=\"pos\">[4]</span> You can reach me at this e-mail address or at 248-555-0973.</p><p>Warmest regards,<br>Chris Alexander</p>"],"vi":"Kính gửi bà Reid,\n\nRất vui được gặp bà tại Hội chợ Thương mại Nhà bán lẻ Mỹ phẩm vừa qua ở San Francisco. Như đã hứa, tôi gửi bà danh mục sản phẩm hiện tại của Modoc Corp. Tôi chắc rằng bà sẽ thấy trong đó có rất nhiều mặt hàng bà quan tâm.\n\nTôi hiểu rằng bà đang tìm cách tăng doanh số cho cửa hàng, và tôi tin sản phẩm của chúng tôi có thể giúp bà đạt mục tiêu này. Chúng tôi có nhiều loại kem dưỡng da mặt, sữa rửa mặt và các sản phẩm chăm sóc da khác. Một trong những sản phẩm bán chạy nhất là Meridian, kem dưỡng ẩm mỏng nhẹ dùng hằng ngày. Khách hàng rất thích vì nó không có mùi hương, nên họ không phải lo nó sẽ lẫn với nước hoa hay các sản phẩm làm đẹp khác.\n\nNếu có câu hỏi nào, tôi rất sẵn lòng trả lời bất cứ lúc nào. Bà có thể liên hệ tôi qua địa chỉ e-mail này hoặc số 248-555-0973.\n\nTrân trọng,\nChris Alexander","qs":[{"n":164,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của e-mail là gì?","opts":["To thank Ms. Reid for a demonstration","To follow through on a request","To register for a trade expo","To set up a business meeting"],"ans":"B","xp":"Câu hỏi mục đích. 'As promised, I'm sending you the current catalog' → thực hiện điều đã hứa/được đề nghị (gửi catalog) → (B).\n(A) Cảm ơn bà Reid về buổi trình diễn (B) Thực hiện một yêu cầu (C) Đăng ký hội chợ (D) Sắp xếp cuộc họp"},{"n":165,"q":"What is implied about Ms. Reid?","qvi":"Điều gì được ngụ ý về bà Reid?","opts":["She tried some free samples.","She lives in San Francisco.","She developed a new perfume.","She works in the field of cosmetics."],"ans":"D","xp":"Câu hỏi suy luận. Hai người gặp ở 'Cosmetics Retailers Trade Expo' và bà muốn 'boost sales in your shop' bằng sản phẩm chăm sóc da → bà làm trong ngành mỹ phẩm → (D). (B) hội chợ ở San Francisco chứ không nói bà sống ở đó.\n(A) Đã dùng thử mẫu miễn phí (B) Sống ở San Francisco (C) Phát triển nước hoa mới (D) Làm trong ngành mỹ phẩm"},{"n":166,"q":"What benefit of Meridian is mentioned?","qvi":"Lợi ích nào của Meridian được nhắc đến?","opts":["It does not have any odor.","It is environmentally friendly.","It lasts for a long time.","It comes in various sizes."],"ans":"A","xp":"Câu hỏi chi tiết. 'Customers love it because it is fragrance-free' → không có mùi → (A). fragrance-free = does not have any odor.\n(A) Không có mùi (B) Thân thiện môi trường (C) Dùng được lâu (D) Có nhiều kích cỡ"},{"n":167,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"I'm sure you'll find that it has numerous items you'll be interested in.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào: \"Tôi chắc rằng bà sẽ thấy trong đó có rất nhiều mặt hàng bà quan tâm.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"A","xp":"Điền câu. 'it has numerous items' – 'it' phải chỉ một thứ chứa nhiều mặt hàng → 'the current catalog' ngay trước vị trí [1] → (A)."}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Kelly Ward [1:30 P.M.]</b></p><p>Good afternoon. I've invited Esther Tsao to this chat, as she has volunteered to assist with the planning.</p></div><div class=\"msg\"><p><b>Esther Tsao [1:31 P.M.]</b></p><p>I'm happy to be a part of this event. My roofing business, which has now been closed, always sold a lot of materials from our booth at the conference over the years.</p></div><div class=\"msg\"><p><b>Kelly Ward [1:32 P.M.]</b></p><p>I'm glad to hear that. Now you'll be able to participate from the other side of things.</p></div><div class=\"msg\"><p><b>Herbert Inez [1:34 P.M.]</b></p><p>We're glad to have your help. Adding a second day for the first time creates some unique challenges. For example, the only site I found that is available for the weekend of October 8th is Orchard Hall. It's not as conveniently located as Toliver Plaza, where we've held the event before, but it's much more affordable.</p></div><div class=\"msg\"><p><b>Kelly Ward [1:35 P.M.]</b></p><p>That's perfect. Could you contact Orchard Hall today so that we can put down a deposit and lock in the dates?</p></div><div class=\"msg\"><p><b>Herbert Inez [1:36 P.M.]</b></p><p>Sure. And I'll try to negotiate a discount for conference attendees staying on site.</p></div><div class=\"msg\"><p><b>Esther Tsao [1:38 P.M.]</b></p><p>Has the guest speaker for the evening session been selected yet?</p></div><div class=\"msg\"><p><b>Kelly Ward [1:39 P.M.]</b></p><p>We have invited Marcel Dillon to do it.</p></div><div class=\"msg\"><p><b>Esther Tsao [1:40 P.M.]</b></p><p>He would be fantastic! I saw photos of the latest building he designed in New York, and it is a masterpiece.</p></div><div class=\"msg\"><p><b>Herbert Inez [1:42 P.M.]</b></p><p>I agree. I'm sure a lot of people will be interested in hearing what he has to say.</p></div><div class=\"msg\"><p><b>Kelly Ward [1:43 P.M.]</b></p><p>Exactly! I expect to get confirmation from him sometime this week.</p></div>"],"vi":"Kelly Ward [1:30]: Chào buổi chiều. Tôi đã mời Esther Tsao vào cuộc trò chuyện này vì chị ấy tình nguyện hỗ trợ khâu lên kế hoạch.\nEsther Tsao [1:31]: Tôi rất vui được tham gia sự kiện này. Công ty lợp mái của tôi, giờ đã đóng cửa, trước đây năm nào cũng bán được nhiều vật liệu tại gian hàng ở hội nghị.\nKelly Ward [1:32]: Thật vui khi nghe vậy. Giờ chị sẽ được tham gia ở vai trò ngược lại.\nHerbert Inez [1:34]: Rất vui có chị giúp sức. Lần đầu tiên thêm ngày thứ hai tạo ra một số thử thách riêng. Ví dụ, địa điểm duy nhất tôi tìm được còn trống vào cuối tuần ngày 8 tháng 10 là Orchard Hall. Nó không ở vị trí thuận tiện như Toliver Plaza, nơi chúng ta từng tổ chức, nhưng rẻ hơn nhiều.\nKelly Ward [1:35]: Vậy là hoàn hảo. Anh có thể liên hệ Orchard Hall hôm nay để đặt cọc và chốt ngày không?\nHerbert Inez [1:36]: Được. Tôi cũng sẽ thử thương lượng giảm giá cho người tham dự hội nghị ở lại tại chỗ.\nEsther Tsao [1:38]: Diễn giả khách mời cho phiên buổi tối đã được chọn chưa?\nKelly Ward [1:39]: Chúng tôi đã mời Marcel Dillon.\nEsther Tsao [1:40]: Ông ấy sẽ rất tuyệt! Tôi đã xem ảnh tòa nhà mới nhất ông ấy thiết kế ở New York, đó là một kiệt tác.\nHerbert Inez [1:42]: Tôi đồng ý. Chắc chắn nhiều người sẽ muốn nghe ông ấy chia sẻ.\nKelly Ward [1:43]: Đúng vậy! Tôi mong sẽ nhận được xác nhận của ông ấy trong tuần này.","qs":[{"n":168,"q":"What is indicated about Ms. Tsao?","qvi":"Điều gì được nói về bà Tsao?","opts":["She has participated in the conference as a vendor.","She is responsible for decorating the booths.","She will give a presentation at the conference.","She plans to put her business up for sale."],"ans":"A","xp":"Câu hỏi chi tiết. 'My roofing business... always sold a lot of materials from our booth at the conference over the years' → bà từng tham gia hội nghị với tư cách người bán hàng → (A).\n(A) Từng tham gia hội nghị với tư cách nhà cung cấp/bán hàng (B) Phụ trách trang trí gian hàng (C) Sẽ thuyết trình (D) Định bán công ty"},{"n":169,"q":"What is suggested about this year's conference?","qvi":"Điều gì được gợi ý về hội nghị năm nay?","opts":["Its venue is conveniently located.","Its admission rates will be raised.","It will be longer than previous ones.","It will be held in New York."],"ans":"C","xp":"Câu hỏi suy luận. 'Adding a second day for the first time' → năm nay kéo dài hơn các năm trước → (C). (A) sai: Orchard Hall 'not as conveniently located'.\n(A) Địa điểm thuận tiện (B) Phí vào cửa sẽ tăng (C) Sẽ dài hơn các lần trước (D) Tổ chức ở New York"},{"n":170,"q":"At 1:35 P.M., what does Ms. Ward mean when she writes, \"That's perfect\"?","qvi":"Lúc 1:35, bà Ward có ý gì khi viết \"That's perfect\"?","opts":["She is glad that Mr. Inez has finalized a contract.","She likes the event dates that Mr. Inez selected.","She is satisfied with the venue they will use.","She thinks the guest speaker will do a great job."],"ans":"C","xp":"Câu hỏi hàm ý. Ông Inez vừa nói Orchard Hall là địa điểm duy nhất còn trống và 'much more affordable'; bà Ward đáp 'That's perfect' rồi nhờ liên hệ đặt cọc → bà hài lòng với địa điểm → (C). (A) chưa ký hợp đồng (mới định đặt cọc).\n(A) Vui vì ông Inez đã chốt hợp đồng (B) Thích ngày tổ chức ông Inez chọn (C) Hài lòng với địa điểm (D) Nghĩ diễn giả sẽ làm tốt"},{"n":171,"q":"Who most likely is Marcel Dillon?","qvi":"Marcel Dillon nhiều khả năng là ai?","opts":["A journalist","A fashion designer","An event planner","An architect"],"ans":"D","xp":"Câu hỏi suy luận. 'I saw photos of the latest building he designed in New York' → ông thiết kế tòa nhà → kiến trúc sư → (D).\n(A) Nhà báo (B) Nhà thiết kế thời trang (C) Người tổ chức sự kiện (D) Kiến trúc sư"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following Web page.","passages":["<h3>Seymour Music Hall</h3><h4>Go Beyond the Music!</h4><p>Spring is the perfect time to visit Seymour Music Hall and enjoy music-related programs and activities. Every Wednesday at noon, we offer a free concert to the public to showcase the talents of students taking lessons in our music tutoring program.</p><p><b>Hours of Operation:</b><br>Monday-Thursday 10 A.M.-6 P.M. / Friday 11 A.M.-8 P.M. / Saturday-Sunday 11 A.M.-7 P.M. / Closed on all major holidays.</p><p><b>Current Exhibits:</b><br><i>Music Through the Ages</i> (permanent collection): Rio Room<br><i>Modern Jazz</i>: Amber Room<br><i>Instruments Across the Globe</i>: Dunbar Room</p><p><b>Lectures:</b><br><b>March 16, 6:30 P.M.</b><br>Ranjeet Sardar, the conductor of the Surat Symphony Orchestra, discusses how to choose the instrument that is right for you based on your interest and physical attributes. This information can be especially helpful for children who are joining an orchestra or band for the first time.</p><p><b>April 20, 6:30 P.M.</b><br>Jihee Kim, who has been creating designs for album covers and concert posters for over a decade, explains how she translates the emotions of the music into pictures.</p><p><b>May 18, 7:30 P.M.</b><br>Archie Bouley, curator of the \"Modern Jazz\" exhibit on display in the Amber Room, discusses her research methods. Her goal for the exhibit was to show how jazz trends develop and change.</p>"],"vi":"Nhà hát Âm nhạc Seymour – Vượt ra ngoài âm nhạc!\n\nMùa xuân là thời điểm tuyệt vời để ghé thăm Nhà hát Âm nhạc Seymour và tận hưởng các chương trình, hoạt động liên quan đến âm nhạc. Mỗi thứ Tư lúc 12 giờ trưa, chúng tôi tổ chức buổi hòa nhạc miễn phí cho công chúng để giới thiệu tài năng của các học viên trong chương trình dạy nhạc của chúng tôi.\n\nGiờ mở cửa: Thứ Hai–Thứ Năm 10h–18h / Thứ Sáu 11h–20h / Thứ Bảy–Chủ Nhật 11h–19h / Đóng cửa vào tất cả các ngày lễ lớn.\n\nCác triển lãm hiện tại: Âm nhạc qua các thời kỳ (trưng bày cố định): phòng Rio; Jazz hiện đại: phòng Amber; Nhạc cụ khắp thế giới: phòng Dunbar.\n\nCác buổi nói chuyện:\n16/3, 18:30 – Ranjeet Sardar, nhạc trưởng Dàn nhạc Giao hưởng Surat, bàn về cách chọn nhạc cụ phù hợp dựa trên sở thích và đặc điểm cơ thể. Thông tin này đặc biệt hữu ích cho trẻ em lần đầu tham gia dàn nhạc hoặc ban nhạc.\n20/4, 18:30 – Jihee Kim, người đã thiết kế bìa album và áp phích hòa nhạc hơn mười năm, giải thích cách cô chuyển cảm xúc của âm nhạc thành hình ảnh.\n18/5, 19:30 – Archie Bouley, người phụ trách triển lãm \"Jazz hiện đại\" ở phòng Amber, bàn về phương pháp nghiên cứu của mình. Mục tiêu của bà là cho thấy các xu hướng nhạc jazz phát triển và thay đổi như thế nào.","qs":[{"n":172,"q":"What is indicated on the Web page about Seymour Music Hall?","qvi":"Trang web cho biết điều gì về Nhà hát Âm nhạc Seymour?","opts":["Its exhibits change every month.","It is offering free music lessons.","Its on-site lectures require tickets.","It is open to the public daily."],"ans":"D","xp":"Câu hỏi chi tiết. Giờ mở cửa ghi đủ từ Thứ Hai đến Chủ Nhật (chỉ đóng ngày lễ lớn) → mở cửa hằng ngày → (D). (A) có trưng bày cố định; (B) hòa nhạc miễn phí chứ không phải lớp học miễn phí; (C) không nhắc vé.\n(A) Triển lãm thay đổi hằng tháng (B) Dạy nhạc miễn phí (C) Buổi nói chuyện cần vé (D) Mở cửa cho công chúng mỗi ngày"},{"n":173,"q":"What is NOT a topic that is covered in Seymour Music Hall's current exhibits?","qvi":"Chủ đề nào KHÔNG có trong các triển lãm hiện tại?","opts":["Trends in a particular genre","International musical instruments","The history of music","Modern recording techniques"],"ans":"D","xp":"Câu hỏi NOT. (A) xu hướng của một thể loại = Modern Jazz (xu hướng jazz); (B) nhạc cụ quốc tế = Instruments Across the Globe; (C) lịch sử âm nhạc = Music Through the Ages. Không có triển lãm về kỹ thuật thu âm → (D).\n(A) Xu hướng của một thể loại (B) Nhạc cụ các nước (C) Lịch sử âm nhạc (D) Kỹ thuật thu âm hiện đại"},{"n":174,"q":"Who most likely is Ms. Kim?","qvi":"Bà Kim nhiều khả năng là ai?","opts":["A film producer","A music critic","A graphic designer","A professional musician"],"ans":"C","xp":"Câu hỏi suy luận. 'Jihee Kim, who has been creating designs for album covers and concert posters' → thiết kế bìa album, áp phích → nhà thiết kế đồ họa → (C).\n(A) Nhà sản xuất phim (B) Nhà phê bình âm nhạc (C) Nhà thiết kế đồ họa (D) Nhạc công chuyên nghiệp"},{"n":175,"q":"What will lecture attendees learn about in April?","qvi":"Người dự buổi nói chuyện tháng 4 sẽ học về điều gì?","opts":["Capturing feelings in visual form","Improving music-playing techniques","Researching famous musicians","Selecting a musical instrument"],"ans":"A","xp":"Câu hỏi chi tiết. April 20: 'explains how she translates the emotions of the music into pictures' → thể hiện cảm xúc bằng hình ảnh → (A). (D) là buổi tháng 3.\n(A) Thể hiện cảm xúc dưới dạng hình ảnh (B) Cải thiện kỹ thuật chơi nhạc (C) Nghiên cứu nhạc sĩ nổi tiếng (D) Chọn nhạc cụ"}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following e-mail and letter.","passages":["<div class=\"hdr\"><p><b>To:</b> Raul Wolfe &lt;r.wolfe@wolfetiles.com&gt;</p><p><b>From:</b> Kelly Wagner &lt;kellywagner@anokabank.com&gt;</p><p><b>Date:</b> March 19</p><p><b>Subject:</b> Business Loan through Anoka Bank</p></div><p>Dear Mr. Wolfe,</p><p>My name is Kelly Wagner. I am following up on the appointment you had on March 4 regarding a loan for your dress-making business. I understand that you originally met with Constance Gauthier, but she has transferred to another branch, so I am taking over for her. As I'm sure Ms. Gauthier explained, the loan amount is dependent on your business's financial situation. Your business needs at least $125,000 in annual earnings for each of the past two years to be issued a $25,000 loan. If your annual earnings for each of the past two years have been $200,000 or more, then you would be eligible to receive $40,000.</p><p>The next step in processing your application is for you to send documents for verification. I will need a copy of your business plan, documents showing the salary payments to employees, your sixteen-digit business license number, and an overview of your business account for the past two years.</p><p>If the loan is approved, you will be notified by mail, and the loan amount will be deposited into your bank account three days after the approval date. As soon as the funds are deposited, you can access them for any business purpose.</p><p>Warmest regards,<br>Kelly Wagner</p>","<p>Raul Wolfe<br>524 Boswell Court<br>San Diego, CA 92101</p><p>April 7</p><p>Dear Mr. Wolfe,</p><p>We are pleased to inform you that Anoka Bank approved your business loan request this morning. Enclosed you will find a copy of the loan agreement, which you should retain for your records. A lump sum of $40,000 will be deposited in your bank account, and the payments will begin from May 15. A payment of $864.79 will be automatically taken from your account on the 15th of every month for a period of 60 months (five years). If you prefer, you may make larger payment in order to pay the loan off early.</p><p>Should you have any questions, please feel free to contact your designated loan officer, Kelly Wagner, at 555-7947, extension 24.</p><p>Thank you for being an Anoka Bank customer!</p><p>The Anoka Bank Loans Team</p>"],"vi":"[E-mail] Kính gửi ông Wolfe,\n\nTôi là Kelly Wagner. Tôi xin tiếp nối cuộc hẹn của ông vào ngày 4 tháng 3 về khoản vay cho doanh nghiệp may váy áo của ông. Tôi được biết ban đầu ông đã gặp bà Constance Gauthier, nhưng bà ấy đã chuyển sang chi nhánh khác nên tôi sẽ tiếp quản thay bà. Chắc hẳn bà Gauthier đã giải thích rằng số tiền vay phụ thuộc vào tình hình tài chính của doanh nghiệp. Doanh nghiệp của ông cần có thu nhập hằng năm ít nhất 125.000 đô la trong mỗi năm của hai năm qua để được vay 25.000 đô la. Nếu thu nhập hằng năm của mỗi năm trong hai năm qua từ 200.000 đô la trở lên, ông sẽ đủ điều kiện nhận 40.000 đô la.\n\nBước tiếp theo để xử lý hồ sơ là ông gửi giấy tờ để xác minh. Tôi cần bản sao kế hoạch kinh doanh, giấy tờ thể hiện việc trả lương cho nhân viên, mã số giấy phép kinh doanh 16 chữ số và bản tổng quan tài khoản doanh nghiệp trong hai năm qua.\n\nNếu khoản vay được duyệt, ông sẽ được thông báo qua thư, và tiền vay sẽ được chuyển vào tài khoản ba ngày sau ngày duyệt. Ngay khi tiền được chuyển vào, ông có thể dùng cho bất kỳ mục đích kinh doanh nào.\n\nTrân trọng,\nKelly Wagner\n\n[Thư] Ngày 7 tháng 4\n\nKính gửi ông Wolfe,\n\nChúng tôi vui mừng thông báo Ngân hàng Anoka đã duyệt yêu cầu vay vốn kinh doanh của ông sáng nay. Kèm theo là bản sao hợp đồng vay, ông nên giữ lại để lưu hồ sơ. Khoản tiền 40.000 đô la sẽ được chuyển một lần vào tài khoản của ông, và việc trả nợ bắt đầu từ ngày 15 tháng 5. Khoản 864,79 đô la sẽ được tự động trừ từ tài khoản của ông vào ngày 15 hằng tháng trong 60 tháng (5 năm). Nếu muốn, ông có thể trả nhiều hơn để tất toán khoản vay sớm.\n\nNếu có thắc mắc, xin liên hệ nhân viên tín dụng phụ trách của ông, bà Kelly Wagner, số 555-7947, máy lẻ 24.\n\nCảm ơn ông đã là khách hàng của Ngân hàng Anoka!\nBộ phận Cho vay Ngân hàng Anoka","qs":[{"n":176,"q":"What is implied about Ms. Wagner?","qvi":"Điều gì được ngụ ý về bà Wagner?","opts":["She recently transferred to a new branch.","She is Ms. Gauthier's supervisor.","She has not met Mr. Wolfe in person.","She would like to reschedule a meeting."],"ans":"C","xp":"Câu hỏi suy luận. 'My name is Kelly Wagner... you originally met with Constance Gauthier... I am taking over for her' → bà Wagner tự giới thiệu, chưa gặp ông Wolfe trực tiếp → (C). (A) người chuyển chi nhánh là bà Gauthier.\n(A) Mới chuyển sang chi nhánh mới (B) Là cấp trên của bà Gauthier (C) Chưa gặp trực tiếp ông Wolfe (D) Muốn dời cuộc họp"},{"n":177,"q":"What is NOT requested by Ms. Wagner for Mr. Wolfe's application?","qvi":"Bà Wagner KHÔNG yêu cầu giấy tờ nào?","opts":["The original business license","A business plan","Payment records","An account summary"],"ans":"A","xp":"Câu hỏi NOT. Bà cần 'a copy of your business plan' (B), 'documents showing the salary payments' (C), 'an overview of your business account' (D), và chỉ cần 'your sixteen-digit business license number' (mã số), không cần bản gốc giấy phép → (A).\n(A) Bản gốc giấy phép kinh doanh (B) Kế hoạch kinh doanh (C) Hồ sơ trả lương (D) Bản tóm tắt tài khoản"},{"n":178,"q":"When will Mr. Wolfe be able to access the loan funds for the first time?","qvi":"Khi nào ông Wolfe có thể dùng tiền vay lần đầu?","opts":["On April 7","On April 8","On April 10","On April 15"],"ans":"C","xp":"Câu hỏi kết hợp 2 bài. E-mail: tiền được chuyển 'three days after the approval date', và 'As soon as the funds are deposited, you can access them'. Thư (ngày 7/4): khoản vay được duyệt 'this morning' → 7/4 + 3 ngày = 10/4 → (C)."},{"n":179,"q":"What is suggested about Mr. Wolfe's business?","qvi":"Điều gì được gợi ý về doanh nghiệp của ông Wolfe?","opts":["It operates in more than one city.","It opened two years ago.","It will undergo a building project.","It earned at least $200,000 last year."],"ans":"D","xp":"Câu hỏi kết hợp. Thư: ông nhận 'A lump sum of $40,000'. E-mail: được vay 40.000 đô la khi thu nhập mỗi năm trong hai năm qua 'have been $200,000 or more' → năm ngoái doanh nghiệp kiếm ít nhất 200.000 đô la → (D).\n(A) Hoạt động ở nhiều thành phố (B) Mở cửa hai năm trước (C) Sắp có dự án xây dựng (D) Năm ngoái thu ít nhất 200.000 đô la"},{"n":180,"q":"According to the letter, what part of the loan agreement is flexible?","qvi":"Theo thư, phần nào của hợp đồng vay là linh hoạt?","opts":["The lump sum amount","The monthly due date","The interest rate","The duration of payments"],"ans":"D","xp":"Câu hỏi chi tiết. 'If you prefer, you may make larger payment in order to pay the loan off early' → có thể trả xong sớm hơn 60 tháng → thời hạn trả nợ linh hoạt → (D).\n(A) Số tiền giải ngân (B) Ngày đến hạn hằng tháng (C) Lãi suất (D) Thời hạn trả nợ"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following Web page and e-mail.","passages":["<p>José Acevedo knew that he wanted to be a writer from a very young age. As a young boy growing up in Toronto, where he still lives today, he wrote short stories for his family and friends. He received a university degree in journalism before working at the <i>Toronto Daily Herald</i>. During that time, he was awarded the McKinley Prize, which is given for top reporting in a newspaper format. Mr. Acevedo then started publishing his own books, and he has four titles to date.</p><p><b><i>Plastic Universe</i>, published 2012</b><br>A look into the modern world's addiction to plastic and its effects on wildlife and the environment. The book helped to further the discussion across the country on plastic use and its downsides.</p><p><b><i>Wind Revolution</i>, published 2015</b><br>The book traces the history of wind turbines and their growing popularity as a sustainable energy source. It also outlines how individuals can get involved with using turbines on their own property.</p><p><b><i>Catching Up</i>, published 2016</b><br>Acevedo interviews Toronto City Council members to investigate their efforts to adapt laws to the changing needs of the public, especially regarding technology and the environment.</p><p><b><i>Texas Treasures</i>, published 2017</b><br>An undercover investigation into the oil industry in the U.S. state of Texas. Acevedo examines essential topics such as worker health, environmental protection, and corporate greed.</p>","<div class=\"hdr\"><p><b>To:</b> José Acevedo &lt;contact@joseacevedo.com&gt;</p><p><b>From:</b> Namiyo Sawada &lt;n.sawada@zlproductions.com&gt;</p><p><b>Date:</b> August 30</p><p><b>Subject:</b> Documentary</p></div><p>Dear Mr. Acevedo,</p><p>I am currently working on a documentary, and I believe that the details from your latest book would be a great addition to my film. Your insights would be highly valuable to our viewers. I first became familiar with your work when my book club read your debut novel, and I have followed your career since then. I wanted to introduce myself first, but I will call you tomorrow to arrange a time to meet, if you are interested. I can come your way so you don't have to travel.</p><p>Warmest regards,<br>Namiyo Sawada<br>ZL Productions</p>"],"vi":"[Trang web] José Acevedo biết mình muốn trở thành nhà văn từ khi còn rất nhỏ. Khi còn là cậu bé lớn lên ở Toronto, nơi ông vẫn sống đến nay, ông viết truyện ngắn cho gia đình và bạn bè. Ông lấy bằng đại học ngành báo chí trước khi làm việc tại tờ Toronto Daily Herald. Trong thời gian đó, ông được trao giải McKinley, giải thưởng dành cho bài phóng sự xuất sắc nhất trên báo in. Sau đó ông Acevedo bắt đầu xuất bản sách của riêng mình, đến nay đã có bốn cuốn.\n\nPlastic Universe (2012): Cái nhìn về sự lệ thuộc vào nhựa của thế giới hiện đại và tác động của nó đến động vật hoang dã và môi trường. Cuốn sách góp phần thúc đẩy cuộc thảo luận trên cả nước về việc dùng nhựa và mặt trái của nó.\nWind Revolution (2015): Cuốn sách kể lại lịch sử tua-bin gió và sự phổ biến ngày càng tăng của nó như một nguồn năng lượng bền vững. Sách cũng hướng dẫn cách cá nhân có thể dùng tua-bin trên đất của mình.\nCatching Up (2016): Acevedo phỏng vấn các thành viên Hội đồng thành phố Toronto để tìm hiểu nỗ lực của họ trong việc điều chỉnh luật theo nhu cầu thay đổi của người dân, nhất là về công nghệ và môi trường.\nTexas Treasures (2017): Một cuộc điều tra bí mật về ngành dầu mỏ ở bang Texas, Mỹ. Acevedo xem xét những chủ đề thiết yếu như sức khỏe người lao động, bảo vệ môi trường và lòng tham của doanh nghiệp.\n\n[E-mail] Kính gửi ông Acevedo,\n\nTôi đang thực hiện một phim tài liệu và tôi tin rằng các chi tiết trong cuốn sách mới nhất của ông sẽ là phần bổ sung tuyệt vời cho bộ phim. Những hiểu biết sâu sắc của ông sẽ rất có giá trị với khán giả của chúng tôi. Tôi biết đến tác phẩm của ông lần đầu khi câu lạc bộ sách của tôi đọc cuốn sách đầu tay của ông, và tôi đã theo dõi sự nghiệp của ông kể từ đó. Tôi muốn tự giới thiệu trước, và ngày mai tôi sẽ gọi cho ông để sắp xếp thời gian gặp, nếu ông quan tâm. Tôi có thể đến chỗ ông để ông không phải đi lại.\n\nTrân trọng,\nNamiyo Sawada\nZL Productions","qs":[{"n":181,"q":"Who are the intended recipients of the McKinley Prize?","qvi":"Giải McKinley dành cho ai?","opts":["Novelists","Film directors","Newspaper journalists","Environmental activists"],"ans":"C","xp":"Câu hỏi chi tiết. 'the McKinley Prize, which is given for top reporting in a newspaper format' → dành cho phóng viên báo in → (C).\n(A) Tiểu thuyết gia (B) Đạo diễn phim (C) Nhà báo viết báo in (D) Nhà hoạt động môi trường"},{"n":182,"q":"What is implied about Mr. Acevedo?","qvi":"Điều gì được ngụ ý về ông Acevedo?","opts":["He installed wind turbines on his property.","He spoke with his local politicians.","He has opened a new office in Texas.","He will teach a university course."],"ans":"B","xp":"Câu hỏi suy luận. Ông sống ở Toronto ('where he still lives today') và trong Catching Up 'Acevedo interviews Toronto City Council members' → ông đã nói chuyện với chính trị gia địa phương → (B).\n(A) Lắp tua-bin gió trên đất nhà (B) Đã nói chuyện với các chính trị gia địa phương (C) Mở văn phòng ở Texas (D) Sẽ dạy đại học"},{"n":183,"q":"Which book does Ms. Sawada want to feature in a documentary?","qvi":"Bà Sawada muốn đưa cuốn sách nào vào phim tài liệu?","opts":["Plastic Universe","Wind Revolution","Catching Up","Texas Treasures"],"ans":"D","xp":"Câu hỏi kết hợp. E-mail: 'the details from your latest book'. Trang web: sách mới nhất là Texas Treasures (2017) → (D)."},{"n":184,"q":"What does Ms. Sawada hope to do on August 31?","qvi":"Bà Sawada hy vọng làm gì vào ngày 31 tháng 8?","opts":["Set up an appointment","Attend a meeting","Release a video","Announce a book club"],"ans":"A","xp":"Câu hỏi chi tiết. E-mail gửi ngày 30/8: 'I will call you tomorrow to arrange a time to meet' → ngày 31/8 bà gọi để hẹn gặp → (A).\n(A) Sắp xếp cuộc hẹn (B) Dự họp (C) Phát hành video (D) Thông báo câu lạc bộ sách"},{"n":185,"q":"In the e-mail, the word \"way\" in paragraph 1, line 5, is closest in meaning to","qvi":"Từ \"way\" trong e-mail gần nghĩa nhất với","opts":["method","style","feature","direction"],"ans":"D","xp":"Câu hỏi đồng nghĩa. 'I can come your way so you don't have to travel' = tôi có thể đến phía/chỗ của ông → way = hướng, phía → (D) direction. (A) method 'phương pháp' là nghĩa khác của way, không hợp ở đây."}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following e-mails and schedule.","passages":["<div class=\"hdr\"><p><b>To:</b> All Valley Realty Employees</p><p><b>From:</b> William Monahan</p><p><b>Date:</b> September 18</p><p><b>Subject:</b> Upcoming software training</p><p><b>Attachment:</b> training.docx</p></div><p>Dear Valley Realty Employees,</p><p>Please be aware that employees will be required to complete mandatory software training in the first half of October. There are two programs that will be covered by the training. Investiprop-7 must be installed on all company computers, and we will start using it for all property searches instead of the EstateMax program. It is much more user-friendly, and there are more options for adding specific search criteria. All employees must complete the training, but they can select the date. The other program is Slate Books Pro, which is billing software. The program has recently undergone several upgrades. Only accountants need to take the Slate Books Pro training, and it will be provided on-site in our conference room.</p><p>Thanks,<br>William Monahan<br>Office Manager, Valley Realty</p>","<h3>Valley Realty Training Schedule</h3><table><tr><th>Date</th><th>Software Program</th><th>Format</th><th>Number of Modules</th><th>Time</th></tr><tr><td>October 2</td><td>Investiprop-7</td><td>Online</td><td>6</td><td>10:30 A.M.-12:30 P.M.</td></tr><tr><td>October 5</td><td>Slate Books Pro</td><td>On-site workshop</td><td>4</td><td>2:00 P.M.-4:00 P.M.</td></tr><tr><td>October 6</td><td>Investiprop-7</td><td>Online</td><td>6</td><td>10:30 A.M.-12:30 P.M.</td></tr><tr><td>October 8</td><td>Investiprop-7</td><td>On-site workshop</td><td>6</td><td>1:00 P.M.-4:00 P.M.</td></tr><tr><td>October 10</td><td>Slate Books Pro</td><td>On-site workshop</td><td>4</td><td>9:00 A.M.-11:00 A.M.</td></tr><tr><td>October 13</td><td>Investiprop-7</td><td>Online</td><td>6</td><td>2:00 P.M.-4:00 P.M.</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> William Monahan</p><p><b>From:</b> Tabitha Foster</p><p><b>Date:</b> September 19</p><p><b>Subject:</b> RE: Upcoming software training</p></div><p>Dear Mr. Monahan,</p><p>I am required to undergo training for both software programs, but I'm afraid I have some scheduling conflicts. I have already been approved to take my annual vacation from October 1 to October 7. I'll also be in Dallas from October 10 to 14 for the National Realtors Convention. Please call me at extension 21 so we can talk about how to resolve this issue.</p><p>Thanks!<br>Tabitha Foster</p>"],"vi":"[E-mail 1] Gửi toàn thể nhân viên Valley Realty,\n\nXin lưu ý rằng nhân viên bắt buộc phải hoàn thành khóa đào tạo phần mềm trong nửa đầu tháng 10. Khóa đào tạo gồm hai chương trình. Investiprop-7 phải được cài trên tất cả máy tính của công ty, và chúng ta sẽ bắt đầu dùng nó cho mọi việc tìm kiếm bất động sản thay cho chương trình EstateMax. Nó dễ dùng hơn nhiều và có nhiều tùy chọn hơn để thêm tiêu chí tìm kiếm cụ thể. Tất cả nhân viên phải hoàn thành khóa này nhưng được tự chọn ngày. Chương trình còn lại là Slate Books Pro, phần mềm lập hóa đơn. Chương trình này vừa được nâng cấp nhiều lần. Chỉ kế toán viên cần học Slate Books Pro, và khóa này được tổ chức tại phòng hội nghị của công ty.\n\n[Lịch đào tạo] 2/10 Investiprop-7, trực tuyến, 6 học phần, 10:30–12:30; 5/10 Slate Books Pro, hội thảo tại chỗ, 4 học phần, 14:00–16:00; 6/10 Investiprop-7, trực tuyến, 6 học phần, 10:30–12:30; 8/10 Investiprop-7, hội thảo tại chỗ, 6 học phần, 13:00–16:00; 10/10 Slate Books Pro, tại chỗ, 4 học phần, 9:00–11:00; 13/10 Investiprop-7, trực tuyến, 6 học phần, 14:00–16:00.\n\n[E-mail 2] Kính gửi ông Monahan,\n\nTôi phải học cả hai phần mềm, nhưng e là tôi bị trùng lịch. Tôi đã được duyệt nghỉ phép năm từ 1 đến 7 tháng 10. Tôi cũng sẽ ở Dallas từ 10 đến 14 tháng 10 để dự Hội nghị Môi giới Bất động sản Quốc gia. Xin ông gọi cho tôi theo số máy lẻ 21 để chúng ta bàn cách giải quyết.\n\nCảm ơn!\nTabitha Foster","qs":[{"n":186,"q":"What is mentioned about Investiprop-7?","qvi":"Điều gì được nhắc đến về Investiprop-7?","opts":["It can track customer billing information.","It is intended to replace another program.","It has recently changed some of its features.","It requires an account and password."],"ans":"B","xp":"Câu hỏi chi tiết. 'we will start using it for all property searches instead of the EstateMax program' → thay thế chương trình khác → (B). (A)(C) là Slate Books Pro (phần mềm hóa đơn, vừa nâng cấp).\n(A) Theo dõi thông tin hóa đơn (B) Dùng để thay thế chương trình khác (C) Vừa đổi một số tính năng (D) Cần tài khoản và mật khẩu"},{"n":187,"q":"What is the same about all Investiprop-7 training sessions?","qvi":"Điểm chung của mọi buổi đào tạo Investiprop-7 là gì?","opts":["They are all held on the Internet.","They last for the same amount of time.","They all take place in the morning.","They have the same number of modules."],"ans":"D","xp":"Câu hỏi chi tiết (bảng). Các buổi Investiprop-7 (2/10, 6/10, 8/10, 13/10) đều có 6 học phần → (D). (A) buổi 8/10 tại chỗ; (B) buổi 8/10 kéo dài 3 tiếng; (C) buổi 8/10 và 13/10 vào buổi chiều.\n(A) Đều học trên mạng (B) Thời lượng như nhau (C) Đều vào buổi sáng (D) Số học phần như nhau"},{"n":188,"q":"What is implied about Ms. Foster?","qvi":"Điều gì được ngụ ý về bà Foster?","opts":["She plans to transfer to the Dallas branch.","She is a newly hired employee.","She works as an accountant.","She had difficulty installing the software."],"ans":"C","xp":"Câu hỏi kết hợp. Bà Foster: 'I am required to undergo training for both software programs'. E-mail 1: 'Only accountants need to take the Slate Books Pro training' → bà là kế toán → (C).\n(A) Định chuyển đến chi nhánh Dallas (B) Nhân viên mới (C) Làm kế toán (D) Gặp khó khi cài phần mềm"},{"n":189,"q":"When will Ms. Foster most likely undergo training?","qvi":"Bà Foster nhiều khả năng sẽ học vào ngày nào?","opts":["On October 6","On October 8","On October 10","On October 13"],"ans":"B","xp":"Câu hỏi kết hợp. Bà nghỉ phép 1–7/10 và ở Dallas 10–14/10 → ngày 6, 10, 13 đều bận; chỉ còn buổi 8/10 (Investiprop-7) → (B)."},{"n":190,"q":"Why is Mr. Monahan asked to call Ms. Foster?","qvi":"Tại sao ông Monahan được đề nghị gọi cho bà Foster?","opts":["To provide an updated schedule","To discuss solutions to a problem","To confirm attendance at a convention","To approve a vacation request"],"ans":"B","xp":"Câu hỏi chi tiết. 'Please call me at extension 21 so we can talk about how to resolve this issue' → bàn cách giải quyết vấn đề → (B).\n(A) Cung cấp lịch mới (B) Bàn giải pháp cho một vấn đề (C) Xác nhận dự hội nghị (D) Duyệt đơn nghỉ phép"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following Web page, order form, and e-mail.","passages":["<h3>Hampstead</h3><p>For the past twenty years, Hampstead has been supplying landscaping materials and equipment in the Culver City area. We're open annually from early spring to mid-fall, and we can help you create the outdoor space of your dreams whether you are shopping for your business or your family home.</p><p>We work hard to provide affordable goods, with a wide range of options to suit all tastes and budgets. We try to source our goods from businesses in and around Culver City whenever possible, as this supports the local economy and reduces pollution caused by transportation. In addition to our product line, we also offer</p><ul><li>Free local delivery on all orders exceeding $35</li><li>Garden design services (whether ornamental or for crops)</li><li>Fast and easy ordering by phone or online</li><li>Referrals for landscaping professionals in your area</li></ul><p>We accept returns for any reason within 30 days of the delivery date. Bagged items such as soil and wood chips must be unopened. If you receive damaged goods or the wrong item, we will reimburse you for the return shipping costs. Otherwise, you must cover those costs yourself.</p>","<h3>Hampstead</h3><p><b>Name:</b> Ray Casper <b>Order Date:</b> May 24 <b>Delivery Date:</b> May 26<br><b>Delivery Address:</b> 442 Emerson Road, Culver City, CA 90230</p><table><tr><th>Description</th><th>Product ID</th><th>Price Per Unit</th><th>Qty.</th><td></td></tr><tr><td>Solar LED path lights (pack of 4)</td><td>NR5472</td><td>$29.99</td><td>10</td><td>$299.90</td></tr><tr><td>Raised garden bed, wooden frame (48' x 96' x 5.5')</td><td>HL195</td><td>$99.99</td><td>3</td><td>$299.97</td></tr><tr><td>Shredded wood mulch (50-lb bag)</td><td>HL3810</td><td>$8.99</td><td>5</td><td>$44.95</td></tr><tr><td>Grey stones (20-lb bag)</td><td>PS024</td><td>$23.49</td><td>5</td><td>$117.45</td></tr><tr><td>Metal garden edging (black, 75-ft roll)</td><td>AE638</td><td>$319.49</td><td>1</td><td>$319.49</td></tr><tr><td>For questions or comments about your order, please e-mail info@hampstead4u.com.</td><td></td><td></td><td>Subtotal</td><td>$1,081.76</td></tr><tr><td></td><td></td><td></td><td>Tax</td><td>$64.90</td></tr><tr><td></td><td></td><td></td><td>Delivery</td><td>$0.00</td></tr><tr><td></td><td></td><td></td><td>Total</td><td>$1,146.66</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> Ray Casper &lt;r.casper@lomaxltd.com&gt;</p><p><b>From:</b> Mara Brewer &lt;m.brewer@lomaxltd.com&gt;</p><p><b>Date:</b> June 2</p><p><b>Subject:</b> Landscaping</p></div><p>Hi Ray,</p><p>Thanks for ordering the materials that the maintenance team needs for the landscaping work in front of our building. I've used goods from a variety of stores, and these items from Hampstead are by far the best I've seen. I'm sure they will last for a long time. We are making steady progress on the changes, but we're running low on rocks, so I've ordered more of those. Also, one of the garden beds had a crack in it when it arrived, so we should exchange it. It would be best for you to contact Hampstead about that, since you placed the original order.</p><p>Thanks!<br>Mara</p>"],"vi":"[Trang web] Hampstead\n\nHai mươi năm qua, Hampstead cung cấp vật liệu và dụng cụ làm cảnh quan ở khu vực Culver City. Chúng tôi mở cửa hằng năm từ đầu mùa xuân đến giữa mùa thu, và có thể giúp bạn tạo nên không gian ngoài trời mơ ước dù bạn mua cho doanh nghiệp hay cho gia đình.\n\nChúng tôi nỗ lực cung cấp hàng hóa giá phải chăng với nhiều lựa chọn phù hợp mọi sở thích và ngân sách. Chúng tôi cố gắng nhập hàng từ các doanh nghiệp trong và quanh Culver City bất cứ khi nào có thể, vì điều này hỗ trợ kinh tế địa phương và giảm ô nhiễm do vận chuyển. Ngoài các sản phẩm, chúng tôi còn cung cấp: giao hàng miễn phí trong khu vực cho đơn trên 35 đô la; dịch vụ thiết kế vườn (vườn cảnh hay vườn trồng cây); đặt hàng nhanh, dễ qua điện thoại hoặc trực tuyến; giới thiệu thợ làm cảnh quan trong khu vực.\n\nChúng tôi nhận trả hàng vì bất kỳ lý do gì trong vòng 30 ngày kể từ ngày giao. Hàng đóng bao như đất và vụn gỗ phải chưa mở. Nếu bạn nhận hàng bị hỏng hoặc sai hàng, chúng tôi sẽ hoàn lại phí gửi trả. Nếu không, bạn phải tự chịu phí đó.\n\n[Phiếu đặt hàng] Tên: Ray Casper – Ngày đặt: 24/5 – Ngày giao: 26/5 – Địa chỉ: 442 Emerson Road, Culver City. Đèn LED năng lượng mặt trời lối đi (gói 4) NR5472, 10 gói; luống vườn nâng khung gỗ HL195, 3 cái; vụn gỗ phủ gốc (bao 50 pound) HL3810, 5 bao; đá xám (bao 20 pound) PS024, 5 bao; viền vườn bằng kim loại (cuộn 75 feet) AE638, 1 cuộn. Tạm tính 1.081,76 đô la; thuế 64,90; giao hàng 0; tổng 1.146,66 đô la.\n\n[E-mail] Chào Ray,\n\nCảm ơn anh đã đặt vật liệu mà đội bảo trì cần cho việc làm cảnh quan trước tòa nhà của chúng ta. Tôi đã dùng hàng của nhiều cửa hàng, và các món của Hampstead là tốt nhất tôi từng thấy. Tôi chắc chúng sẽ dùng được rất lâu. Việc cải tạo đang tiến triển đều, nhưng chúng ta sắp hết đá nên tôi đã đặt thêm. Ngoài ra, một luống vườn bị nứt khi giao đến nên chúng ta cần đổi. Tốt nhất anh nên liên hệ Hampstead về việc đó vì anh là người đặt đơn ban đầu.\n\nCảm ơn!\nMara","qs":[{"n":191,"q":"What is true about Hampstead?","qvi":"Điều nào đúng về Hampstead?","opts":["It has branches in several cities.","It provides a rental service.","It is operated by a family.","It is a seasonal business."],"ans":"D","xp":"Câu hỏi chi tiết. 'We're open annually from early spring to mid-fall' → chỉ mở cửa theo mùa → (D).\n(A) Có chi nhánh ở nhiều thành phố (B) Cho thuê dụng cụ (C) Do một gia đình điều hành (D) Kinh doanh theo mùa"},{"n":192,"q":"Which aspect of Hampstead is mentioned on the Web page?","qvi":"Trang web nhắc đến khía cạnh nào của Hampstead?","opts":["Cultivating its own plants","Supporting local businesses","Hiring experienced crew members","Training landscaping professionals"],"ans":"B","xp":"Câu hỏi chi tiết. 'We try to source our goods from businesses in and around Culver City... as this supports the local economy' → hỗ trợ doanh nghiệp địa phương → (B). (D) họ chỉ giới thiệu (referrals) thợ, không đào tạo.\n(A) Tự trồng cây (B) Hỗ trợ doanh nghiệp địa phương (C) Thuê thợ giàu kinh nghiệm (D) Đào tạo thợ làm cảnh quan"},{"n":193,"q":"What does Ms. Brewer like about Hampstead?","qvi":"Bà Brewer thích điều gì ở Hampstead?","opts":["It delivers items quickly.","It offers a long warranty.","It has high-quality goods.","It carries a wide selection."],"ans":"C","xp":"Câu hỏi chi tiết. 'these items from Hampstead are by far the best I've seen. I'm sure they will last for a long time' → hàng chất lượng cao → (C).\n(A) Giao hàng nhanh (B) Bảo hành dài (C) Hàng chất lượng cao (D) Nhiều lựa chọn"},{"n":194,"q":"Which product has Ms. Brewer ordered?","qvi":"Bà Brewer đã đặt sản phẩm nào?","opts":["NR5472","HL195","HL3810","PS024"],"ans":"D","xp":"Câu hỏi kết hợp. E-mail: 'we're running low on rocks, so I've ordered more of those'. Phiếu đặt hàng: đá = Grey stones, mã PS024 → (D)."},{"n":195,"q":"How will Hampstead most likely respond to Mr. Casper's request?","qvi":"Hampstead nhiều khả năng sẽ phản hồi yêu cầu của ông Casper thế nào?","opts":["By providing express delivery","By making a free repair","By issuing a full refund for a product","By reimbursing shipping costs"],"ans":"D","xp":"Câu hỏi kết hợp. E-mail: một luống vườn bị nứt khi giao đến, cần đổi. Trang web: 'If you receive damaged goods... we will reimburse you for the return shipping costs' → hoàn phí vận chuyển → (D).\n(A) Giao hàng nhanh (B) Sửa miễn phí (C) Hoàn tiền toàn bộ (D) Hoàn phí vận chuyển"}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following advertisement, form, and e-mail.","passages":["<h3>Bryson Camping Spring Sale</h3><p>Stock up on essential goods at our Spring Sale. One week only—April 2-8.</p><table><tr><td>All Kolbert sleeping bags $29.99 each</td><td>10% off all Hathaway flashlights</td><td>60% off select outdoor stoves</td><td>$15 off all Forestlife backpacks</td><td>30% off all Benson 2- and 3-person tents</td></tr></table><p>Coupons cannot be used with certain sale prices.<br>Check our Web site for details.</p>","<h3>Bryson Camping</h3><h4>Customer Inquiry/Comment Form</h4><p><b>Customer Name:</b> Rachel Barry<br><b>Company Name (if applicable):</b> Adventure Tours<br><b>E-mail Address:</b> rachelb@adventuretoursltd.net<br><b>Loyalty Card Number (if applicable):</b> 7625003<br><b>File Upload:</b> receipt.jpg<br><b>Inquiry/Comment:</b> I recently purchased a large order of supplies for our customers' overnight camping trips. This included 5 Renway sleeping bags, 20 Hathaway flashlights, 8 Benson tents (the 3-person size), and 3 Forestlife backpacks. I saw on your Web site that most of these items are now being offered at discounted prices because of your Spring Sale. I have uploaded a copy of my receipt for review. I hope you will apply your 30-day price match to my order so that I can take advantage of the discount.</p>","<div class=\"hdr\"><p><b>To:</b> Rachel Barry &lt;rachelb@adventuretoursltd.net&gt;</p><p><b>From:</b> Bryson Camping &lt;inquiries@brysoncamping.com&gt;</p><p><b>Date:</b> April 4</p><p><b>Subject:</b> Bryson Camping Customer Inquiry/Comment</p></div><p>Dear Ms. Barry,</p><p>Thank you for contacting Bryson Camping. You are correct that we refund the difference if the price drops within 30 days of the purchase date. However, some of the sale prices are not as low as what you have already received. For example, you got half off the Benson tents because the product was first offered at an introductory rate, as it was new to the market. You also received a bulk discount on items that were ordered in groups of ten or more. Therefore, you will only receive a partial refund for the Forestlife products. It will be sent along with a new receipt for those items within five business days.</p><p>We would love to know what you think about our inquiry process via the attached survey. If you send it back, you will be entered into a prize drawing for a $50 store voucher.</p><p>Justin Dugan<br>Customer Service Agent, Bryson Camping</p>"],"vi":"[Quảng cáo] Đợt giảm giá mùa xuân của Bryson Camping – Hãy mua sắm đồ dùng thiết yếu trong đợt giảm giá mùa xuân. Chỉ một tuần – từ 2 đến 8 tháng 4. Túi ngủ Kolbert 29,99 đô la/chiếc; giảm 10% đèn pin Hathaway; giảm 60% một số bếp dã ngoại; giảm 15 đô la ba lô Forestlife; giảm 30% lều Benson 2 và 3 người. Không áp dụng phiếu giảm giá cùng một số mức giá khuyến mãi. Xem chi tiết trên trang web.\n\n[Phiếu góp ý] Tên khách hàng: Rachel Barry – Công ty: Adventure Tours – Số thẻ thành viên: 7625003 – Tệp tải lên: receipt.jpg. Nội dung: Gần đây tôi đã mua một lượng lớn đồ dùng cho các chuyến cắm trại qua đêm của khách hàng chúng tôi, gồm 5 túi ngủ Renway, 20 đèn pin Hathaway, 8 lều Benson (loại 3 người) và 3 ba lô Forestlife. Tôi thấy trên trang web rằng phần lớn các món này hiện đang giảm giá nhờ đợt giảm giá mùa xuân. Tôi đã tải lên bản sao hóa đơn để quý vị xem xét. Tôi mong quý vị áp dụng chính sách bù chênh lệch giá trong 30 ngày cho đơn hàng của tôi để tôi được hưởng mức giảm giá.\n\n[E-mail] Kính gửi bà Barry,\n\nCảm ơn bà đã liên hệ Bryson Camping. Bà nói đúng rằng chúng tôi hoàn lại phần chênh lệch nếu giá giảm trong vòng 30 ngày kể từ ngày mua. Tuy nhiên, một số mức giá khuyến mãi không thấp bằng mức bà đã được hưởng. Ví dụ, bà được giảm một nửa giá lều Benson vì sản phẩm này lúc đầu được bán với giá giới thiệu do mới ra mắt thị trường. Bà cũng được giảm giá mua số lượng lớn cho các mặt hàng đặt từ mười cái trở lên. Vì vậy, bà sẽ chỉ được hoàn một phần tiền cho sản phẩm Forestlife. Khoản tiền sẽ được gửi kèm hóa đơn mới cho các món đó trong vòng năm ngày làm việc.\n\nChúng tôi rất muốn biết bà nghĩ gì về quy trình giải đáp thắc mắc qua bản khảo sát đính kèm. Nếu bà gửi lại, bà sẽ được tham gia rút thăm trúng phiếu mua hàng 50 đô la.\n\nJustin Dugan\nNhân viên Chăm sóc Khách hàng, Bryson Camping","qs":[{"n":196,"q":"What is implied about Ms. Barry?","qvi":"Điều gì được ngụ ý về bà Barry?","opts":["She was recently hired as a tour guide.","She was misinformed about a store policy.","She made a purchase before April 2.","She visited the store 30 days ago."],"ans":"C","xp":"Câu hỏi kết hợp. Bà mua hàng rồi mới thấy 'these items are now being offered at discounted prices because of your Spring Sale' (bắt đầu 2/4) và muốn được bù chênh lệch → bà đã mua trước ngày 2/4 → (C). (B) sai: nhân viên xác nhận bà hiểu đúng chính sách ('You are correct').\n(A) Mới được tuyển làm hướng dẫn viên (B) Bị thông tin sai về chính sách (C) Đã mua hàng trước ngày 2/4 (D) Đến cửa hàng 30 ngày trước"},{"n":197,"q":"Why does Ms. Barry want the business to review a receipt?","qvi":"Tại sao bà Barry muốn cửa hàng xem hóa đơn?","opts":["To issue a refund for damaged items","To process a request for a price change","To confirm that some items were not shipped","To check whether an employee made an error"],"ans":"B","xp":"Câu hỏi chi tiết. 'I have uploaded a copy of my receipt for review. I hope you will apply your 30-day price match to my order' → xử lý yêu cầu điều chỉnh giá → (B).\n(A) Hoàn tiền hàng hỏng (B) Xử lý yêu cầu điều chỉnh giá (C) Xác nhận hàng chưa gửi (D) Kiểm tra lỗi nhân viên"},{"n":198,"q":"According to Mr. Dugan, why was Ms. Barry given a discount on the Benson items?","qvi":"Theo ông Dugan, tại sao bà Barry được giảm giá lều Benson?","opts":["She signed up for a loyalty club program.","She took advantage of a product launch.","She purchased a large number of goods.","She presented a discount coupon."],"ans":"B","xp":"Câu hỏi chi tiết. 'you got half off the Benson tents because the product was first offered at an introductory rate, as it was new to the market' → giá ưu đãi khi ra mắt sản phẩm → (B). (C) giảm giá số lượng lớn áp dụng cho món đặt từ 10 cái (đèn pin), không phải lều (8 cái).\n(A) Đăng ký chương trình thành viên (B) Tận dụng đợt ra mắt sản phẩm (C) Mua số lượng lớn (D) Dùng phiếu giảm giá"},{"n":199,"q":"For which items will Ms. Barry receive a new receipt?","qvi":"Bà Barry sẽ nhận hóa đơn mới cho món nào?","opts":["Backpacks","Flashlights","Sleeping bags","Tents"],"ans":"A","xp":"Câu hỏi kết hợp. E-mail: 'you will only receive a partial refund for the Forestlife products... along with a new receipt for those items'. Quảng cáo/phiếu: sản phẩm Forestlife là ba lô (backpacks) → (A)."},{"n":200,"q":"What has Mr. Dugan sent with the e-mail?","qvi":"Ông Dugan gửi kèm gì theo e-mail?","opts":["Some survey results","A store voucher","Some discount codes","A feedback form"],"ans":"D","xp":"Câu hỏi chi tiết. 'We would love to know what you think about our inquiry process via the attached survey' → đính kèm phiếu khảo sát lấy ý kiến = feedback form → (D). (B) phiếu 50 đô la chỉ là giải rút thăm.\n(A) Kết quả khảo sát (B) Phiếu mua hàng (C) Mã giảm giá (D) Phiếu góp ý"}]}]}};
